    fun getActivityById(id: Long): SelfidoActivityDef? {


        return allActivities.firstOrNull { it.id == id }


    }





    /**


     * Returns the structured activity map for the selected gender and top-level category.


     * E.g. For DRESSING + BOY:


     *   "Upper Body Dressing" -> [T-Shirt, Shirt, Zip-Up Jacket, Undergarment - Vest]


     *   "Lower Body Dressing" -> [Trousers with Knot, Jeans Pant, Elastic Shorts, Undergarment - Briefs]


     */


    fun getActivitiesForGenderAndCategory(


        gender: String,


        category: String


    ): Map<String, List<SelfidoActivityDef>> {


        val normGender = if (gender.uppercase().startsWith("G") || gender.uppercase().startsWith("F")) "GIRL" else "BOY"


        val normCat = category.uppercase()





        return when (normCat) {


            "DRESSING" -> {


                if (normGender == "BOY") {


                    linkedMapOf(


                        "Upper Body Dressing" to allActivities.filter { it.category == "DRESSING" && it.subCategory == "UPPER_BODY" && (it.targetGender == "BOY" || it.targetGender == "ALL") },


                        "Lower Body Dressing" to allActivities.filter { it.category == "DRESSING" && it.subCategory == "LOWER_BODY" && (it.targetGender == "BOY" || it.targetGender == "ALL") }


                    )


                } else {


                    linkedMapOf(


                        "Upper Body Dressing" to allActivities.filter { it.category == "DRESSING" && it.subCategory == "UPPER_BODY" && (it.targetGender == "GIRL" || it.targetGender == "ALL") },


                        "Lower Body Dressing" to allActivities.filter { it.category == "DRESSING" && it.subCategory == "LOWER_BODY" && (it.targetGender == "GIRL" || it.targetGender == "ALL") }


                    )


                }


            }


            "SHOES" -> {


                linkedMapOf(


                    "Socks" to allActivities.filter { it.category == "SHOES" && it.subCategory == "SOCKS" },


                    "Shoes" to allActivities.filter { it.category == "SHOES" && it.subCategory == "SHOES" }


                )


            }


            "EATING" -> {


                linkedMapOf(


                    "Eating with Hands" to allActivities.filter { it.category == "EATING" && it.subCategory == "HANDS" },


                    "Eating with Utensils" to allActivities.filter { it.category == "EATING" && it.subCategory == "UTENSILS" }


                )


            }


            else -> emptyMap()


        }


    }





    /**


     * Fallback clinical task steps for each activity directly from the SELFIDO Task Analysis.


     */


    fun getStepsForActivity(activityId: Long): List<TaskStepResponse> {
        val raw = stepsRawMap[activityId] ?: emptyList()
        return raw.mapIndexed { idx, s ->
            val stepNum = idx + 1
            val mediaList = if (activityId == 1L) {
                listOf(
                    MediaResponse(
                        id = 1000L + stepNum,
                        mediaType = "IMAGE_GIF",
                        mediaUrl = "file:///android_asset/dressing/boy/tshirt/step_${String.format("%02d", stepNum)}.gif",
                        thumbnailUrl = "file:///android_asset/dressing/boy/tshirt/step_${String.format("%02d", stepNum)}.gif",
                        caption = s.first
                    )
                )
            } else if (activityId == 2L) {
                listOf(
                    MediaResponse(
                        id = 2000L + stepNum,
                        mediaType = "IMAGE_GIF",
                        mediaUrl = "file:///android_asset/dressing/boy/shirt/step_${String.format("%02d", stepNum)}.gif",
                        thumbnailUrl = "file:///android_asset/dressing/boy/shirt/step_${String.format("%02d", stepNum)}.gif",
                        caption = s.first
                    )
                )
            } else {
                emptyList()
            }
            TaskStepResponse(
                id = (activityId * 1000 + stepNum),
                activityId = activityId,
                stepNumber = stepNum,
                title = s.first,
                titleTa = s.second,
                instructionText = s.third,
                instructionTextTa = s.fourth,
                childInstruction = s.fifth,
                childInstructionTa = s.sixth,
                audioPromptUrl = null,
                audioPromptUrlTa = null,
                media = mediaList
            )
        }
    }

