            StepTuple("Stand in front of the trousers", "\u0b95\u0bbe\u0bb2\u0bcd\u0b9a\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bbf\u0ba9\u0bcd \u0bae\u0bc1\u0ba9\u0bcd \u0ba8\u0bbf\u0bb1\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child stands facing open trousers.", "\u0b95\u0bbe\u0bb2\u0bcd\u0b9a\u0b9f\u0bcd\u0b9f\u0bc8\u0b95\u0bcd\u0b95\u0bc1 \u0bae\u0bc1\u0ba9\u0bcd \u0ba8\u0bc7\u0bb0\u0bbe\u0b95 \u0ba8\u0bbf\u0bb1\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Stand in front of your trousers!", "\u0b95\u0bbe\u0bb2\u0bcd\u0b9a\u0b9f\u0bcd\u0b9f\u0bc8 \u0bae\u0bc1\u0ba9\u0bcd \u0ba8\u0bbf\u0bb2\u0bcd!"),


