            StepTuple("Pick up the trousers using both hands", "\u0b87\u0bb0\u0bc1 \u0b95\u0bc8\u0b95\u0bb3\u0bbe\u0bb2\u0bc1\u0bae\u0bcd \u0b95\u0bbe\u0bb2\u0bcd\u0b9a\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child lifts trousers securely.", "\u0b87\u0bb0\u0bc1 \u0b95\u0bc8\u0b95\u0bb3\u0bbe\u0bb2\u0bc1\u0bae\u0bcd \u0b95\u0bbe\u0bb2\u0bcd\u0b9a\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0bae\u0bc7\u0bb2\u0bc7 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Pick up your trousers with both hands!", "\u0b87\u0bb0\u0bc1 \u0b95\u0bc8\u0b95\u0bb3\u0bbe\u0bb2\u0bc1\u0bae\u0bcd \u0b95\u0bbe\u0bb2\u0bcd\u0b9a\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0b8e\u0b9f\u0bc1!"),


            StepTuple("Identify the front and back", "\u0bae\u0bc1\u0ba9\u0bcd\u0baa\u0bc1\u0bb1\u0bae\u0bcd \u0bae\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0baa\u0bbf\u0ba9\u0bcd\u0baa\u0bc1\u0bb1\u0ba4\u0bcd\u0ba4\u0bc8 \u0b85\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child locates drawstrings in front.", "\u0bae\u0bc1\u0ba9\u0bcd\u0baa\u0bc1\u0bb1 \u0ba8\u0bbe\u0b9f\u0bbe\u0bb5\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0baa\u0bbf\u0ba9\u0bcd\u0baa\u0b95\u0bcd\u0b95\u0ba4\u0bcd\u0ba4\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b85\u0b9f\u0bc8\u0baf\u0bbe\u0bb3\u0bae\u0bcd \u0b95\u0bbe\u0ba3\u0bb5\u0bc1\u0bae\u0bcd.", "Find the drawstrings in the front!", "\u0bae\u0bc1\u0ba9\u0bcd\u0baa\u0b95\u0bcd\u0b95 \u0ba8\u0bbe\u0b9f\u0bbe\u0bb5\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bc1\u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Find the waistband", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child finds top circular waistband.", "\u0bae\u0bc7\u0bb2\u0bcd \u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8\u0ba4\u0bcd \u0ba4\u0bca\u0b9f\u0bb5\u0bc1\u0bae\u0bcd.", "Find the waistband at the top!", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8\u0ba4\u0bcd \u0ba4\u0bca\u0b9f\u0bc1!"),


            StepTuple("Find the right leg opening", "\u0bb5\u0bb2\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0bcd \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0ba4\u0bcd\u0ba4\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child locates right pant leg.", "\u0bb5\u0bb2\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0bcd \u0b95\u0bc1\u0bb4\u0bbe\u0baf\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Find the right leg hole!", "\u0bb5\u0bb2\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0bcd \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0ba4\u0bcd\u0ba4\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bc1\u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Find the left leg opening", "\u0b87\u0b9f\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0bcd \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0ba4\u0bcd\u0ba4\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child locates left pant leg.", "\u0b87\u0b9f\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0bcd \u0b95\u0bc1\u0bb4\u0bbe\u0baf\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Find the left leg hole!", "\u0b87\u0b9f\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0bcd \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0ba4\u0bcd\u0ba4\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bc1\u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Hold the waistband with both hands", "\u0b87\u0bb0\u0bc1 \u0b95\u0bc8\u0b95\u0bb3\u0bbe\u0bb2\u0bc1\u0bae\u0bcd \u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child grips left and right waistband.", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0b87\u0bb0\u0bc1 \u0b95\u0bc8\u0b95\u0bb3\u0bbe\u0bb2\u0bc1\u0bae\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Hold the waistband open with both hands!", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0b87\u0bb0\u0bc1 \u0b95\u0bc8\u0b95\u0bb3\u0bbe\u0bb2\u0bc1\u0bae\u0bcd \u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Step one foot into the correct leg opening", "\u0b92\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0bc8 \u0b9a\u0bb0\u0bbf\u0baf\u0bbe\u0ba9 \u0b95\u0bbe\u0bb2\u0bcd \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0ba4\u0bcd\u0ba4\u0bbf\u0bb2\u0bcd \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child steps foot into opening.", "\u0b92\u0bb0\u0bc1 \u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0b95\u0bbe\u0bb2\u0bcd \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0ba4\u0bcd\u0ba4\u0bbf\u0bb1\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Step your foot into the leg hole!", "\u0b92\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0bc8 \u0b89\u0bb3\u0bcd\u0bb3\u0bc7 \u0bb5\u0bc8!"),


            StepTuple("Push the foot through the leg opening", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0bae\u0bcd \u0bb5\u0bb4\u0bbf\u0baf\u0bc7 \u0bb5\u0bc6\u0bb3\u0bbf\u0baf\u0bc7 \u0ba4\u0bb3\u0bcd\u0bb3\u0bb5\u0bc1\u0bae\u0bcd", "Child extends foot all the way through bottom hem.", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0b95\u0bc0\u0bb4\u0bcd \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0bae\u0bcd \u0bb5\u0bb4\u0bbf\u0baf\u0bc7 \u0bb5\u0bc6\u0bb3\u0bbf\u0baf\u0bc7 \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0bc1 \u0bb5\u0bb0\u0bb5\u0bc1\u0bae\u0bcd.", "Push your foot all the way through!", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0bb5\u0bc6\u0bb3\u0bbf\u0baf\u0bc7 \u0ba4\u0bb3\u0bcd\u0bb3\u0bc1!"),


            StepTuple("Step the other foot into the other leg opening", "\u0bae\u0bb1\u0bcd\u0bb1\u0bca\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0bc8 \u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0ba4\u0bcd\u0ba4\u0bbf\u0bb2\u0bcd \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child lifts second foot into opening.", "\u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0bae\u0bb1\u0bcd\u0bb1 \u0b95\u0bbe\u0bb2\u0bcd \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0ba4\u0bcd\u0ba4\u0bbf\u0bb2\u0bcd \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Step your other foot into the other hole!", "\u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0b95\u0bbe\u0bb2\u0bc8 \u0b89\u0bb3\u0bcd\u0bb3\u0bc7 \u0bb5\u0bc8!"),


            StepTuple("Push the second foot through the leg opening", "\u0b87\u0bb0\u0ba3\u0bcd\u0b9f\u0bbe\u0bb5\u0ba4\u0bc1 \u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0bb5\u0bc6\u0bb3\u0bbf\u0baf\u0bc7 \u0ba4\u0bb3\u0bcd\u0bb3\u0bb5\u0bc1\u0bae\u0bcd", "Child extends second foot through cuff.", "\u0b87\u0bb0\u0ba3\u0bcd\u0b9f\u0bbe\u0bb5\u0ba4\u0bc1 \u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b95\u0bc0\u0bb4\u0bc7 \u0bb5\u0bc6\u0bb3\u0bbf\u0baf\u0bc7 \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0bc1 \u0bb5\u0bb0\u0bb5\u0bc1\u0bae\u0bcd.", "Push your other foot all the way through!", "\u0bae\u0bb1\u0bc1 \u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0bb5\u0bc6\u0bb3\u0bbf\u0baf\u0bc7 \u0ba4\u0bb3\u0bcd\u0bb3\u0bc1!"),


            StepTuple("Pull the trousers upward from the thighs", "\u0ba4\u0bca\u0b9f\u0bc8 \u0bb5\u0bb0\u0bc8 \u0b95\u0bbe\u0bb2\u0bcd\u0b9a\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0bae\u0bc7\u0bb2\u0bc7 \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child gathers fabric and pulls up to knees/thighs.", "\u0b95\u0bbe\u0bb2\u0bcd\u0b9a\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0bae\u0bc1\u0bb4\u0b99\u0bcd\u0b95\u0bbe\u0bb2\u0bcd \u0bae\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0ba4\u0bca\u0b9f\u0bc8 \u0bb5\u0bb0\u0bc8 \u0bae\u0bc7\u0bb2\u0bc7 \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Pull your trousers up to your thighs!", "\u0ba4\u0bca\u0b9f\u0bc8 \u0bb5\u0bb0\u0bc8 \u0bae\u0bc7\u0bb2\u0bc7 \u0b87\u0bb4\u0bc1!"),


            StepTuple("Stand upright safely", "\u0baa\u0bbe\u0ba4\u0bc1\u0b95\u0bbe\u0baa\u0bcd\u0baa\u0bbe\u0b95 \u0ba8\u0bc7\u0bb0\u0bbe\u0b95 \u0ba8\u0bbf\u0bb1\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child establishes balance.", "\u0b9a\u0bae\u0ba8\u0bbf\u0bb2\u0bc8\u0baf\u0bc1\u0b9f\u0ba9\u0bcd \u0ba8\u0bc7\u0bb0\u0bbe\u0b95 \u0ba8\u0bbf\u0bb1\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Stand up tall and balanced!", "\u0ba8\u0bc7\u0bb0\u0bbe\u0b95 \u0ba8\u0bbf\u0bb2\u0bcd!"),


            StepTuple("Pull the waistband up toward the waist", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1 \u0bb5\u0bb0\u0bc8 \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child raises waistband over hips.", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1 \u0bb5\u0bb0\u0bc8 \u0bae\u0bc7\u0bb2\u0bc7 \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Pull the waistband up to your waist!", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1 \u0bb5\u0bb0\u0bc8 \u0b87\u0bb4\u0bc1!"),


            StepTuple("Check that the waistband is positioned evenly", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8 \u0b9a\u0bc0\u0bb0\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9 \u0b9a\u0bb0\u0bbf\u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child aligns waistband level around hips.", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8 \u0b9a\u0bb0\u0bbf\u0b9a\u0bae\u0bae\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Make sure the waistband is even!", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0b9a\u0bae\u0bae\u0bbe\u0b95\u0bcd\u0b95\u0bc1!"),


            StepTuple("Find the two ends of the drawstring", "\u0ba8\u0bbe\u0b9f\u0bbe\u0bb5\u0bbf\u0ba9\u0bcd \u0b87\u0bb0\u0bc1 \u0bae\u0bc1\u0ba9\u0bc8\u0b95\u0bb3\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child locates both drawstring cords.", "\u0ba8\u0bbe\u0b9f\u0bbe\u0bb5\u0bbf\u0ba9\u0bcd \u0b87\u0bb0\u0bc1 \u0bae\u0bc1\u0ba9\u0bc8\u0b95\u0bb3\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b95\u0bc8\u0b95\u0bb3\u0bbf\u0bb2\u0bcd \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Find both ends of the string!", "\u0b87\u0bb0\u0bc1 \u0ba8\u0bbe\u0b9f\u0bbe \u0bae\u0bc1\u0ba9\u0bc8\u0b95\u0bb3\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bc1\u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Hold one end of the drawstring in each hand", "\u0b92\u0bb5\u0bcd\u0bb5\u0bca\u0bb0\u0bc1 \u0b95\u0bc8\u0baf\u0bbf\u0bb2\u0bc1\u0bae\u0bcd \u0b92\u0bb0\u0bc1 \u0bae\u0bc1\u0ba9\u0bc8\u0baf\u0bc8\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child grips left and right strings.", "\u0b92\u0bb5\u0bcd\u0bb5\u0bca\u0bb0\u0bc1 \u0b95\u0bc8\u0baf\u0bbf\u0bb2\u0bc1\u0bae\u0bcd \u0b92\u0bb0\u0bc1 \u0ba8\u0bbe\u0b9f\u0bbe\u0bb5\u0bc8\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Hold one string in each hand!", "\u0b87\u0bb0\u0bc1 \u0b95\u0bc8\u0b95\u0bb3\u0bbf\u0bb2\u0bc1\u0bae\u0bcd \u0ba8\u0bbe\u0b9f\u0bbe\u0bb5\u0bc8\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Pull both ends to tighten the waistband", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0b87\u0bb1\u0bc1\u0b95\u0bcd\u0b95 \u0ba8\u0bbe\u0b9f\u0bbe\u0b95\u0bcd\u0b95\u0bb3\u0bc8 \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child pulls cords laterally to snug fit.", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0b95\u0bcd\u0b95\u0bc1 \u0ba4\u0b95\u0bc1\u0ba8\u0bcd\u0ba4\u0bb5\u0bbe\u0bb1\u0bc1 \u0b87\u0bb0\u0bc1 \u0ba8\u0bbe\u0b9f\u0bbe\u0b95\u0bcd\u0b95\u0bb3\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Pull both strings to make it snug!", "\u0ba8\u0bbe\u0b9f\u0bbe\u0b95\u0bcd\u0b95\u0bb3\u0bc8 \u0b87\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bc1 \u0b87\u0bb1\u0bc1\u0b95\u0bcd\u0b95\u0bc1!"),


            StepTuple("Cross one drawstring over the other", "\u0b92\u0bb0\u0bc1 \u0ba8\u0bbe\u0b9f\u0bbe\u0bb5\u0bc8 \u0bae\u0bb1\u0bcd\u0bb1\u0bca\u0ba9\u0bcd\u0bb1\u0bbf\u0ba9\u0bcd \u0bae\u0bc7\u0bb2\u0bcd \u0b95\u0bc1\u0bb1\u0bc1\u0b95\u0bcd\u0b95\u0bbe\u0b95 \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child crosses cords forming an X.", "\u0b92\u0bb0\u0bc1 \u0ba8\u0bbe\u0b9f\u0bbe\u0bb5\u0bc8 \u0bae\u0bb1\u0bcd\u0bb1\u0bca\u0ba9\u0bcd\u0bb1\u0bbf\u0ba9\u0bcd \u0bae\u0bc0\u0ba4\u0bc1 \u0b95\u0bc1\u0bb1\u0bc1\u0b95\u0bcd\u0b95\u0bbe\u0b95 \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Cross one string over the other!", "\u0ba8\u0bbe\u0b9f\u0bbe\u0b95\u0bcd\u0b95\u0bb3\u0bc8 \u0b95\u0bc1\u0bb1\u0bc1\u0b95\u0bcd\u0b95\u0bbe\u0b95 \u0bb5\u0bc8!"),


            StepTuple("Make a loop with one end", "\u0b92\u0bb0\u0bc1 \u0bae\u0bc1\u0ba9\u0bc8\u0baf\u0bbf\u0bb2\u0bcd \u0b9a\u0bc1\u0bb0\u0bc1\u0b95\u0bcd\u0b95\u0bc1 \u0bb5\u0bb3\u0bc8\u0baf\u0bae\u0bcd \u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child folds one cord into loop.", "\u0b92\u0bb0\u0bc1 \u0ba8\u0bbe\u0b9f\u0bbe\u0bb5\u0bbf\u0bb2\u0bcd \u0b9a\u0bbf\u0bb1\u0bbf\u0baf \u0bb5\u0bb3\u0bc8\u0baf\u0bae\u0bcd \u0b89\u0bb0\u0bc1\u0bb5\u0bbe\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Make a loop like a bunny ear!", "\u0b92\u0bb0\u0bc1 \u0bae\u0bc1\u0baf\u0bb2\u0bcd \u0b95\u0bbe\u0ba4\u0bc1 \u0baa\u0bcb\u0bb2 \u0bb5\u0bb3\u0bc8\u0baf\u0bae\u0bcd \u0b9a\u0bc6\u0baf\u0bcd!"),


            StepTuple("Wrap the other end around the loop", "\u0bae\u0bb1\u0bcd\u0bb1\u0bca\u0bb0\u0bc1 \u0ba8\u0bbe\u0b9f\u0bbe\u0bb5\u0bc8 \u0bb5\u0bb3\u0bc8\u0baf\u0ba4\u0bcd\u0ba4\u0bc8\u0b9a\u0bcd \u0b9a\u0bc1\u0bb1\u0bcd\u0bb1\u0bbf \u0b9a\u0bc1\u0bb1\u0bcd\u0bb1\u0bb5\u0bc1\u0bae\u0bcd", "Child wraps second cord around base of loop.", "\u0bae\u0bb1\u0bcd\u0bb1\u0bca\u0bb0\u0bc1 \u0ba8\u0bbe\u0b9f\u0bbe\u0bb5\u0bc8 \u0b85\u0ba8\u0bcd\u0ba4 \u0bb5\u0bb3\u0bc8\u0baf\u0ba4\u0bcd\u0ba4\u0bc8\u0b9a\u0bcd \u0b9a\u0bc1\u0bb1\u0bcd\u0bb1\u0bbf \u0b9a\u0bc1\u0bb1\u0bcd\u0bb1\u0bb5\u0bc1\u0bae\u0bcd.", "Wrap the other string around the loop!", "\u0b9a\u0bc1\u0bb1\u0bcd\u0bb1\u0bbf \u0bb5\u0bb3\u0bc8\u0ba4\u0bcd\u0ba4\u0bc1 \u0b8e\u0b9f\u0bc1!"),


            StepTuple("Push the end through to form a knot/bow", "\u0bae\u0bc1\u0ba9\u0bc8\u0baf\u0bc8 \u0ba4\u0bc1\u0bb3\u0bc8 \u0bb5\u0bb4\u0bbf\u0baf\u0bc7 \u0ba4\u0bb3\u0bcd\u0bb3\u0bbf \u0bae\u0bc1\u0b9f\u0bbf\u0b9a\u0bcd\u0b9a\u0bc1 \u0baa\u0bcb\u0b9f\u0bb5\u0bc1\u0bae\u0bcd", "Child pushes loop through center hole.", "\u0ba8\u0bbe\u0b9f\u0bbe\u0bb5\u0bc8 \u0ba8\u0b9f\u0bc1\u0bb5\u0bbf\u0bb2\u0bcd \u0ba4\u0bb3\u0bcd\u0bb3\u0bbf \u0bae\u0bc1\u0b9f\u0bbf\u0b9a\u0bcd\u0b9a\u0bc1 \u0b89\u0bb0\u0bc1\u0bb5\u0bbe\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Push it through to make the bow!", "\u0b89\u0bb3\u0bcd\u0bb3\u0bc7 \u0ba4\u0bb3\u0bcd\u0bb3\u0bbf \u0bae\u0bc1\u0b9f\u0bbf\u0b9a\u0bcd\u0b9a\u0bc1 \u0baa\u0bcb\u0b9f\u0bc1!"),


            StepTuple("Pull both loops/ends to secure the knot", "\u0bae\u0bc1\u0b9f\u0bbf\u0b9a\u0bcd\u0b9a\u0bc8 \u0b87\u0bb1\u0bc1\u0b95\u0bcd\u0b95 \u0b87\u0bb0\u0bc1 \u0bb5\u0bb3\u0bc8\u0baf\u0b99\u0bcd\u0b95\u0bb3\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child tightens bow firmly.", "\u0bae\u0bc1\u0b9f\u0bbf\u0b9a\u0bcd\u0b9a\u0bc8 \u0b89\u0bb1\u0bc1\u0ba4\u0bbf\u0baf\u0bbe\u0b95 \u0b87\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bc1 \u0b87\u0bb1\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Pull both loops tight!", "\u0b87\u0bb0\u0bc1 \u0baa\u0b95\u0bcd\u0b95\u0bae\u0bc1\u0bae\u0bcd \u0b87\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bc1 \u0b95\u0bc6\u0b9f\u0bcd\u0b9f\u0bbf\u0baf\u0bbe\u0b95\u0bcd\u0b95\u0bc1!"),


            StepTuple("Check that the trousers are secure", "\u0b95\u0bbe\u0bb2\u0bcd\u0b9a\u0b9f\u0bcd\u0b9f\u0bc8 \u0ba8\u0bb4\u0bc1\u0bb5\u0bbe\u0bae\u0bb2\u0bcd \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9 \u0b9a\u0bb0\u0bbf\u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child tests snugness around waist.", "\u0b95\u0bbe\u0bb2\u0bcd\u0b9a\u0b9f\u0bcd\u0b9f\u0bc8 \u0ba8\u0bb4\u0bc1\u0bb5\u0bbe\u0bae\u0bb2\u0bcd \u0b9a\u0bb0\u0bbf\u0baf\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9 \u0b89\u0bb1\u0bc1\u0ba4\u0bbf\u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Make sure your trousers stay up!", "\u0b9a\u0bb0\u0bbf\u0baf\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd!"),


            StepTuple("Straighten the trousers around the waist and legs", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1 \u0bae\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0b95\u0bbe\u0bb2\u0bcd\u0b95\u0bb3\u0bbf\u0bb2\u0bcd \u0ba8\u0bc7\u0bb0\u0bbe\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child smooths fabric down legs.", "\u0b95\u0bbe\u0bb2\u0bcd\u0b9a\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bbf\u0bb2\u0bcd \u0b89\u0bb3\u0bcd\u0bb3 \u0b9a\u0bc1\u0bb0\u0bc1\u0b95\u0bcd\u0b95\u0b99\u0bcd\u0b95\u0bb3\u0bc8 \u0ba8\u0bc7\u0bb0\u0bbe\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Smooth down the legs and waist!", "\u0b95\u0bbe\u0bb2\u0bcd\u0b9a\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0ba8\u0bc7\u0bb0\u0bbe\u0b95\u0bcd\u0b95\u0bc1!"),


            StepTuple("Check that both feet and legs are comfortable", "\u0b95\u0bbe\u0bb2\u0bcd\u0b95\u0bb3\u0bcd \u0b87\u0bb0\u0ba3\u0bcd\u0b9f\u0bc1\u0bae\u0bcd \u0bb5\u0b9a\u0ba4\u0bbf\u0baf\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9 \u0b9a\u0bb0\u0bbf\u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child confirms full comfort and mobility.", "\u0ba8\u0b9f\u0ba8\u0bcd\u0ba4\u0bc1 \u0baa\u0bbe\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bc1 \u0bb5\u0b9a\u0ba4\u0bbf\u0baf\u0bc8 \u0b89\u0bb1\u0bc1\u0ba4\u0bbf\u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "All tied! Walk around, you look fantastic!", "\u0bae\u0bc1\u0b9f\u0bbf\u0b9a\u0bcd\u0b9a\u0bc1 \u0baa\u0bcb\u0b9f\u0bcd\u0b9f\u0bbe\u0b9a\u0bcd\u0b9a\u0bc1! \u0b9a\u0bc2\u0baa\u0bcd\u0baa\u0bb0\u0bcd!"),


        ),


        6L to listOf(


            StepTuple("Stand in front of the jeans", "\u0b9c\u0bc0\u0ba9\u0bcd\u0bb8\u0bbf\u0ba9\u0bcd \u0bae\u0bc1\u0ba9\u0bcd \u0ba8\u0bbf\u0bb1\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child faces jeans placed flat.", "\u0b9c\u0bc0\u0ba9\u0bcd\u0bb8\u0bc1\u0b95\u0bcd\u0b95\u0bc1 \u0bae\u0bc1\u0ba9\u0bcd \u0ba8\u0bc7\u0bb0\u0bbe\u0b95 \u0ba8\u0bbf\u0bb1\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Stand in front of your jeans!", "\u0b9c\u0bc0\u0ba9\u0bcd\u0bb8\u0bcd \u0bae\u0bc1\u0ba9\u0bcd \u0ba8\u0bbf\u0bb2\u0bcd!"),


            StepTuple("Look at the jeans", "\u0b9c\u0bc0\u0ba9\u0bcd\u0bb8\u0bc8\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child observes waist and legs.", "\u0b9c\u0bc0\u0ba9\u0bcd\u0bb8\u0bbf\u0ba9\u0bcd \u0b85\u0bae\u0bc8\u0baa\u0bcd\u0baa\u0bc8\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Look at the jeans!", "\u0b9c\u0bc0\u0ba9\u0bcd\u0bb8\u0bc8\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd!"),


            StepTuple("Pick up the jeans using both hands", "\u0b87\u0bb0\u0bc1 \u0b95\u0bc8\u0b95\u0bb3\u0bbe\u0bb2\u0bc1\u0bae\u0bcd \u0b9c\u0bc0\u0ba9\u0bcd\u0bb8\u0bc8 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child lifts jeans by waistband.", "\u0b87\u0bb0\u0bc1 \u0b95\u0bc8\u0b95\u0bb3\u0bbe\u0bb2\u0bc1\u0bae\u0bcd \u0b9c\u0bc0\u0ba9\u0bcd\u0bb8\u0bc8 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Pick up your jeans!", "\u0b9c\u0bc0\u0ba9\u0bcd\u0bb8\u0bc8 \u0b8e\u0b9f\u0bc1!"),


            StepTuple("Identify the front and back", "\u0bae\u0bc1\u0ba9\u0bcd\u0baa\u0bc1\u0bb1\u0bae\u0bcd \u0bae\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0baa\u0bbf\u0ba9\u0bcd\u0baa\u0bc1\u0bb1\u0ba4\u0bcd\u0ba4\u0bc8 \u0b85\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child identifies front zipper/button vs back pockets.", "\u0bae\u0bc1\u0ba9\u0bcd\u0baa\u0b95\u0bcd\u0b95 \u0b9c\u0bbf\u0baa\u0bcd \u0bae\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0baa\u0bbf\u0ba9\u0bcd\u0baa\u0b95\u0bcd\u0b95 \u0baa\u0bc8\u0b95\u0bb3\u0bc8 \u0b85\u0b9f\u0bc8\u0baf\u0bbe\u0bb3\u0bae\u0bcd \u0b95\u0bbe\u0ba3\u0bb5\u0bc1\u0bae\u0bcd.", "Find the button in the front and pockets in the back!", "\u0bae\u0bc1\u0ba9\u0bcd\u0baa\u0b95\u0bcd\u0b95 \u0baa\u0bca\u0ba4\u0bcd\u0ba4\u0bbe\u0ba9\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bc1\u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Find the waistband", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child locates top waistband.", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8\u0ba4\u0bcd \u0ba4\u0bca\u0b9f\u0bb5\u0bc1\u0bae\u0bcd.", "Find the waistband!", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8\u0ba4\u0bcd \u0ba4\u0bca\u0b9f\u0bc1!"),


            StepTuple("Find the right leg opening", "\u0bb5\u0bb2\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0bcd \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0ba4\u0bcd\u0ba4\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child finds right leg opening.", "\u0bb5\u0bb2\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0bcd \u0b95\u0bc1\u0bb4\u0bbe\u0baf\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Find the right leg hole!", "\u0bb5\u0bb2\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0bcd \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0ba4\u0bcd\u0ba4\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bc1\u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Find the left leg opening", "\u0b87\u0b9f\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0bcd \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0ba4\u0bcd\u0ba4\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child finds left leg opening.", "\u0b87\u0b9f\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0bcd \u0b95\u0bc1\u0bb4\u0bbe\u0baf\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Find the left leg hole!", "\u0b87\u0b9f\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0bcd \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0ba4\u0bcd\u0ba4\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bc1\u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Hold the waistband with both hands", "\u0b87\u0bb0\u0bc1 \u0b95\u0bc8\u0b95\u0bb3\u0bbe\u0bb2\u0bc1\u0bae\u0bcd \u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child opens waistband wide.", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0b87\u0bb0\u0bc1 \u0b95\u0bc8\u0b95\u0bb3\u0bbe\u0bb2\u0bc1\u0bae\u0bcd \u0bb5\u0bbf\u0bb0\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Hold the waistband open wide!", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0bb5\u0bbf\u0bb0\u0bbf\u0ba4\u0bcd\u0ba4\u0bc1\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Step one foot into the correct leg opening", "\u0b92\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0bc8 \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0ba4\u0bcd\u0ba4\u0bbf\u0bb2\u0bcd \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child steps foot in.", "\u0b92\u0bb0\u0bc1 \u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0b89\u0bb3\u0bcd\u0bb3\u0bc7 \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Step one foot in!", "\u0b92\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0bc8 \u0b89\u0bb3\u0bcd\u0bb3\u0bc7 \u0bb5\u0bc8!"),


            StepTuple("Push the foot through the leg opening", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0bae\u0bcd \u0bb5\u0bb4\u0bbf\u0baf\u0bc7 \u0bb5\u0bc6\u0bb3\u0bbf\u0baf\u0bc7 \u0ba4\u0bb3\u0bcd\u0bb3\u0bb5\u0bc1\u0bae\u0bcd", "Child pushes foot through cuff.", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0b95\u0bc0\u0bb4\u0bc7 \u0bb5\u0bc6\u0bb3\u0bbf\u0baf\u0bc7 \u0ba4\u0bb3\u0bcd\u0bb3\u0bb5\u0bc1\u0bae\u0bcd.", "Push your foot through!", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0bb5\u0bc6\u0bb3\u0bbf\u0baf\u0bc7 \u0ba4\u0bb3\u0bcd\u0bb3\u0bc1!"),


            StepTuple("Step the other foot into the other leg opening", "\u0bae\u0bb1\u0bcd\u0bb1\u0bca\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0bc8 \u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0ba4\u0bcd\u0ba4\u0bbf\u0bb2\u0bcd \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child steps other foot in.", "\u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0b89\u0bb3\u0bcd\u0bb3\u0bc7 \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Step your other foot in!", "\u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0b95\u0bbe\u0bb2\u0bc8 \u0b89\u0bb3\u0bcd\u0bb3\u0bc7 \u0bb5\u0bc8!"),


            StepTuple("Push the second foot through", "\u0b87\u0bb0\u0ba3\u0bcd\u0b9f\u0bbe\u0bb5\u0ba4\u0bc1 \u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0bb5\u0bc6\u0bb3\u0bbf\u0baf\u0bc7 \u0ba4\u0bb3\u0bcd\u0bb3\u0bb5\u0bc1\u0bae\u0bcd", "Child pushes second foot through cuff.", "\u0b87\u0bb0\u0ba3\u0bcd\u0b9f\u0bbe\u0bb5\u0ba4\u0bc1 \u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0b95\u0bc0\u0bb4\u0bc7 \u0bb5\u0bc6\u0bb3\u0bbf\u0baf\u0bc7 \u0ba4\u0bb3\u0bcd\u0bb3\u0bb5\u0bc1\u0bae\u0bcd.", "Push your other foot through!", "\u0bae\u0bb1\u0bcd\u0bb1\u0bca\u0bb0\u0bc1 \u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0bb5\u0bc6\u0bb3\u0bbf\u0baf\u0bc7 \u0ba4\u0bb3\u0bcd\u0bb3\u0bc1!"),


            StepTuple("Pull the jeans up to the knees", "\u0b9c\u0bc0\u0ba9\u0bcd\u0bb8\u0bc8 \u0bae\u0bc1\u0bb4\u0b99\u0bcd\u0b95\u0bbe\u0bb2\u0bcd \u0bb5\u0bb0\u0bc8 \u0bae\u0bc7\u0bb2\u0bc7 \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child pulls denim up to knees.", "\u0b9c\u0bc0\u0ba9\u0bcd\u0bb8\u0bc8 \u0bae\u0bc1\u0bb4\u0b99\u0bcd\u0b95\u0bbe\u0bb2\u0bcd \u0bb5\u0bb0\u0bc8 \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Pull the jeans up to your knees!", "\u0bae\u0bc1\u0bb4\u0b99\u0bcd\u0b95\u0bbe\u0bb2\u0bcd \u0bb5\u0bb0\u0bc8 \u0b87\u0bb4\u0bc1!"),


            StepTuple("Pull the jeans up toward the thighs", "\u0ba4\u0bca\u0b9f\u0bc8 \u0bb5\u0bb0\u0bc8 \u0b9c\u0bc0\u0ba9\u0bcd\u0bb8\u0bc8 \u0bae\u0bc7\u0bb2\u0bc7 \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child gathers denim up to thighs.", "\u0b9c\u0bc0\u0ba9\u0bcd\u0bb8\u0bc8 \u0ba4\u0bca\u0b9f\u0bc8 \u0bb5\u0bb0\u0bc8 \u0bae\u0bc7\u0bb2\u0bc7 \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Pull the jeans up to your thighs!", "\u0ba4\u0bca\u0b9f\u0bc8 \u0bb5\u0bb0\u0bc8 \u0bae\u0bc7\u0bb2\u0bc7 \u0b87\u0bb4\u0bc1!"),


            StepTuple("Stand upright safely", "\u0baa\u0bbe\u0ba4\u0bc1\u0b95\u0bbe\u0baa\u0bcd\u0baa\u0bbe\u0b95 \u0ba8\u0bc7\u0bb0\u0bbe\u0b95 \u0ba8\u0bbf\u0bb1\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child stands straight.", "\u0b9a\u0bae\u0ba8\u0bbf\u0bb2\u0bc8\u0baf\u0bc1\u0b9f\u0ba9\u0bcd \u0ba8\u0bc7\u0bb0\u0bbe\u0b95 \u0ba8\u0bbf\u0bb1\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Stand up straight!", "\u0ba8\u0bc7\u0bb0\u0bbe\u0b95 \u0ba8\u0bbf\u0bb2\u0bcd!"),


            StepTuple("Pull the waistband up toward the waist", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1 \u0bb5\u0bb0\u0bc8 \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child pulls jeans up over hips.", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1 \u0bb5\u0bb0\u0bc8 \u0b89\u0baf\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bb5\u0bc1\u0bae\u0bcd.", "Pull the waistband up to your waist!", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1 \u0bb5\u0bb0\u0bc8 \u0bae\u0bc7\u0bb2\u0bc7 \u0b87\u0bb4\u0bc1!"),


            StepTuple("Check that the waistband is positioned evenly", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8 \u0b9a\u0bc0\u0bb0\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9 \u0b9a\u0bb0\u0bbf\u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child checks waistband level.", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8 \u0b9a\u0bae\u0bae\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Make sure the waist is even!", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0b9a\u0bae\u0bae\u0bbe\u0b95\u0bcd\u0b95\u0bc1!"),


            StepTuple("Locate the zipper", "\u0b9c\u0bbf\u0baa\u0bcd\u0baa\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child finds front zipper.", "\u0bae\u0bc1\u0ba9\u0bcd\u0baa\u0b95\u0bcd\u0b95 \u0b9c\u0bbf\u0baa\u0bcd\u0baa\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Find the zipper!", "\u0b9c\u0bbf\u0baa\u0bcd\u0baa\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bc1\u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Hold the zipper pull", "\u0b9c\u0bbf\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0baf\u0bc8\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child grasps zipper pull tab.", "\u0b9c\u0bbf\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0baf\u0bc8 \u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bbe\u0bb2\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Hold the zipper tab!", "\u0b9c\u0bbf\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0baf\u0bc8\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Pull the zipper upward until it is fully closed", "\u0b9c\u0bbf\u0baa\u0bcd\u0baa\u0bc8 \u0bae\u0bc1\u0bb4\u0bc1\u0bae\u0bc8\u0baf\u0bbe\u0b95 \u0bae\u0bc7\u0bb2\u0bcd\u0ba8\u0bcb\u0b95\u0bcd\u0b95\u0bbf \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child pulls zipper all the way to top stop.", "\u0b9c\u0bbf\u0baa\u0bcd\u0baa\u0bc8 \u0bae\u0bc7\u0bb2\u0bcd \u0bb5\u0bb0\u0bc8 \u0b87\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bc1 \u0bae\u0bc2\u0b9f\u0bb5\u0bc1\u0bae\u0bcd.", "Zip it all the way up!", "\u0b9c\u0bbf\u0baa\u0bcd\u0baa\u0bc8 \u0bae\u0bc7\u0bb2\u0bc7 \u0b87\u0bb4\u0bc1!"),


            StepTuple("Locate the button and buttonhole", "\u0baa\u0bca\u0ba4\u0bcd\u0ba4\u0bbe\u0ba9\u0bcd \u0bae\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0ba4\u0bc1\u0bb3\u0bc8\u0baf\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child finds metal button and slot.", "\u0b89\u0bb2\u0bcb\u0b95\u0baa\u0bcd \u0baa\u0bca\u0ba4\u0bcd\u0ba4\u0bbe\u0ba9\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0ba4\u0bc1\u0bb3\u0bc8\u0baf\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b85\u0b9f\u0bc8\u0baf\u0bbe\u0bb3\u0bae\u0bcd \u0b95\u0bbe\u0ba3\u0bb5\u0bc1\u0bae\u0bcd.", "Find the button and the hole!", "\u0baa\u0bca\u0ba4\u0bcd\u0ba4\u0bbe\u0ba9\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0ba4\u0bc1\u0bb3\u0bc8\u0baf\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bc1\u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Hold the waistband near the button", "\u0baa\u0bca\u0ba4\u0bcd\u0ba4\u0bbe\u0ba9\u0bc1\u0b95\u0bcd\u0b95\u0bc1 \u0b85\u0bb0\u0bc1\u0b95\u0bbf\u0bb2\u0bcd \u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child braces buttonhole fabric.", "\u0ba4\u0bc1\u0bb3\u0bc8 \u0b89\u0bb3\u0bcd\u0bb3 \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0baf\u0bc8 \u0b92\u0bb0\u0bc1 \u0b95\u0bc8\u0baf\u0bbe\u0bb2\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Hold the waistband near the button!", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0b95\u0bc6\u0b9f\u0bcd\u0b9f\u0bbf\u0baf\u0bbe\u0b95\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf!"),


