            StepTuple("Check that the shorts are comfortable and secure", "\u0b9a\u0b9f\u0bcd\u0b9f\u0bc8 \u0bb5\u0b9a\u0ba4\u0bbf\u0baf\u0bbe\u0b95\u0bb5\u0bc1\u0bae\u0bcd \u0b9a\u0bb0\u0bbf\u0baf\u0bbe\u0b95\u0bb5\u0bc1\u0bae\u0bcd \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child verifies comfort.", "\u0b85\u0bb0\u0bc8\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bcd \u0b9a\u0b9f\u0bcd\u0b9f\u0bc8 \u0bb5\u0b9a\u0ba4\u0bbf\u0baf\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9 \u0b89\u0bb1\u0bc1\u0ba4\u0bbf\u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Comfortable and ready! Great job!", "\u0b9a\u0b9f\u0bcd\u0b9f\u0bc8 \u0baa\u0bcb\u0b9f\u0bcd\u0b9f\u0bbe\u0b9a\u0bcd\u0b9a\u0bc1! \u0b9a\u0baa\u0bbe\u0bb7\u0bcd!"),


        ),


        8L to listOf(


            StepTuple("Sit in a stable position and look at the socks", "\u0ba8\u0bbf\u0bb2\u0bc8\u0baf\u0bbe\u0b95 \u0b85\u0bae\u0bb0\u0bcd\u0ba8\u0bcd\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0b95\u0bb3\u0bc8\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child sits securely on chair or floor and views socks.", "\u0b95\u0bc1\u0bb4\u0ba8\u0bcd\u0ba4\u0bc8 \u0ba8\u0bbf\u0bb2\u0bc8\u0baf\u0bbe\u0b95 \u0b85\u0bae\u0bb0\u0bcd\u0ba8\u0bcd\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0b95\u0bb3\u0bc8\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95 \u0bb5\u0bc7\u0ba3\u0bcd\u0b9f\u0bc1\u0bae\u0bcd.", "Sit nice and steady and look at your socks!", "\u0ba8\u0bbf\u0bb2\u0bc8\u0baf\u0bbe\u0b95 \u0b85\u0bae\u0bb0\u0bcd\u0ba8\u0bcd\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0b95\u0bb3\u0bc8\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd!"),


            StepTuple("Pick up one sock", "\u0b92\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0baf\u0bc8 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child selects and lifts one sock.", "\u0b92\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0baf\u0bc8\u0b95\u0bcd \u0b95\u0bc8\u0baf\u0bbf\u0bb2\u0bcd \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Pick up one sock!", "\u0b92\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0baf\u0bc8 \u0b8e\u0b9f\u0bc1!"),


            StepTuple("Identify the top/opening of the sock", "\u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0baf\u0bbf\u0ba9\u0bcd \u0bae\u0bc7\u0bb2\u0bcd \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0ba4\u0bcd\u0ba4\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child finds opening cuff of sock.", "\u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0baf\u0bbf\u0ba9\u0bcd \u0bae\u0bc7\u0bb2\u0bcd \u0ba4\u0bbf\u0bb1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0baf\u0bc8\u0ba4\u0bcd \u0ba4\u0bca\u0b9f\u0bb5\u0bc1\u0bae\u0bcd.", "Find the opening at the top!", "\u0bae\u0bc7\u0bb2\u0bc7 \u0b89\u0bb3\u0bcd\u0bb3 \u0ba4\u0bbf\u0bb1\u0baa\u0bcd\u0baa\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bc1\u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Identify the heel area of the sock", "\u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bcd \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0baf\u0bc8 \u0b85\u0b9f\u0bc8\u0baf\u0bbe\u0bb3\u0bae\u0bcd \u0b95\u0bbe\u0ba3\u0bb5\u0bc1\u0bae\u0bcd", "Child locates curved heel cup.", "\u0bb5\u0bb3\u0bc8\u0ba8\u0bcd\u0ba4 \u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bcd \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0baf\u0bc8 \u0b85\u0b9f\u0bc8\u0baf\u0bbe\u0bb3\u0bae\u0bcd \u0b95\u0bbe\u0ba3\u0bb5\u0bc1\u0bae\u0bcd.", "Find the heel curve on the sock!", "\u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bcd \u0bb5\u0bb3\u0bc8\u0bb5\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bc1\u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Hold the sock opening with both hands", "\u0b87\u0bb0\u0bc1 \u0b95\u0bc8\u0b95\u0bb3\u0bbe\u0bb2\u0bc1\u0bae\u0bcd \u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8 \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0ba4\u0bcd\u0ba4\u0bc8\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child places both thumbs inside sock opening.", "\u0b87\u0bb0\u0bc1 \u0b95\u0b9f\u0bcd\u0b9f\u0bc8 \u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0bb5\u0bc8\u0ba4\u0bcd\u0ba4\u0bc1\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Hold the opening with both hands!", "\u0b87\u0bb0\u0bc1 \u0b95\u0bc8\u0b95\u0bb3\u0bbe\u0bb2\u0bc1\u0bae\u0bcd \u0ba4\u0bbf\u0bb1\u0baa\u0bcd\u0baa\u0bc8\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Stretch the sock opening slightly", "\u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0ba4\u0bcd\u0ba4\u0bc8 \u0b9a\u0bb1\u0bcd\u0bb1\u0bc1 \u0bb5\u0bbf\u0bb0\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child stretches elastic cuff.", "\u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8 \u0ba4\u0bbf\u0bb1\u0baa\u0bcd\u0baa\u0bc8 \u0b9a\u0bb1\u0bcd\u0bb1\u0bc1 \u0b85\u0b95\u0bb2\u0bae\u0bbe\u0b95 \u0bb5\u0bbf\u0bb0\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Stretch the sock open wide!", "\u0ba4\u0bbf\u0bb1\u0baa\u0bcd\u0baa\u0bc8 \u0b85\u0b95\u0bb2\u0bae\u0bbe\u0b95 \u0bb5\u0bbf\u0bb0\u0bbf!"),


            StepTuple("Open the sock sufficiently", "\u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0ba8\u0bc1\u0bb4\u0bc8\u0baf \u0baa\u0bcb\u0ba4\u0bc1\u0bae\u0bbe\u0ba9 \u0b85\u0bb3\u0bb5\u0bc1 \u0ba4\u0bbf\u0bb1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child scrunches sock ready for toes.", "\u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bcd \u0ba8\u0bc1\u0bb4\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0bb5\u0bb0\u0bc8 \u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0baf\u0bc8\u0b9a\u0bcd \u0b9a\u0bc1\u0bb0\u0bc1\u0b95\u0bcd\u0b95\u0bbf\u0ba4\u0bcd \u0ba4\u0bbf\u0bb1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Scrunch the sock down to the toes!", "\u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0baf\u0bc8 \u0bb5\u0bbf\u0bb0\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd!"),


            StepTuple("Lift one foot toward the hands", "\u0b92\u0bb0\u0bc1 \u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0b95\u0bc8\u0b95\u0bb3\u0bc8 \u0ba8\u0bcb\u0b95\u0bcd\u0b95\u0bbf \u0b89\u0baf\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bb5\u0bc1\u0bae\u0bcd", "Child flexes hip and knee to bring foot up.", "\u0b92\u0bb0\u0bc1 \u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0bae\u0bc7\u0bb2\u0bc7 \u0b89\u0baf\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bb5\u0bc1\u0bae\u0bcd.", "Lift your foot up toward your hands!", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0bae\u0bc7\u0bb2\u0bc7 \u0ba4\u0bc2\u0b95\u0bcd\u0b95\u0bc1!"),


            StepTuple("Place the toes into the sock opening", "\u0b95\u0bbe\u0bb2\u0bcd \u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bc8 \u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child aligns toes with sock opening.", "\u0b95\u0bbe\u0bb2\u0bcd \u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bc8 \u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0ba4\u0bcd \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0ba4\u0bcd\u0ba4\u0bbf\u0bb2\u0bcd \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Put your toes right into the sock!", "\u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bc8 \u0b89\u0bb3\u0bcd\u0bb3\u0bc7 \u0bb5\u0bc8!"),


