            StepTuple("Pull the sock upward toward the ankle", "\u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0baf\u0bc8 \u0b95\u0ba3\u0bc1\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bcd \u0bb5\u0bb0\u0bc8 \u0bae\u0bc7\u0bb2\u0bc7 \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child pulls cuff up around ankle/calf.", "\u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0baf\u0bc8 \u0b95\u0ba3\u0bc1\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bcd \u0bb5\u0bb0\u0bc8 \u0bae\u0bc7\u0bb2\u0bc7 \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Pull the sock up around your ankle!", "\u0b95\u0ba3\u0bc1\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bcd \u0bb5\u0bb0\u0bc8 \u0bae\u0bc7\u0bb2\u0bc7 \u0b87\u0bb4\u0bc1!"),


            StepTuple("Smooth the sock around the toes", "\u0bb5\u0bbf\u0bb0\u0bb2\u0bcd \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0baf\u0bbf\u0bb2\u0bcd \u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0baf\u0bc8 \u0ba8\u0bc7\u0bb0\u0bbe\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child smooths toe fabric flat.", "\u0bb5\u0bbf\u0bb0\u0bb2\u0bcd \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0baf\u0bbf\u0bb2\u0bcd \u0b89\u0bb3\u0bcd\u0bb3 \u0b9a\u0bc1\u0bb0\u0bc1\u0b95\u0bcd\u0b95\u0b99\u0bcd\u0b95\u0bb3\u0bc8 \u0ba8\u0bc0\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Smooth the sock over your toes!", "\u0bb5\u0bbf\u0bb0\u0bb2\u0bcd \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0baf\u0bc8 \u0ba8\u0bc7\u0bb0\u0bbe\u0b95\u0bcd\u0b95\u0bc1!"),


            StepTuple("Smooth the sock around the heel", "\u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bcd \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0baf\u0bbf\u0bb2\u0bcd \u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0baf\u0bc8 \u0ba8\u0bc7\u0bb0\u0bbe\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child aligns heel cup snugly.", "\u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bcd \u0b9a\u0bb0\u0bbf\u0baf\u0bbe\u0b95\u0baa\u0bcd \u0baa\u0bca\u0bb0\u0bc1\u0ba8\u0bcd\u0ba4\u0bc1\u0bae\u0bbe\u0bb1\u0bc1 \u0b9a\u0bb0\u0bbf\u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Make sure the heel fits snug!", "\u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bc8 \u0ba8\u0bc7\u0bb0\u0bbe\u0b95\u0bcd\u0b95\u0bc1!"),


            StepTuple("Straighten the sock around the ankle", "\u0b95\u0ba3\u0bc1\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bbf\u0bb2\u0bcd \u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0baf\u0bc8 \u0ba8\u0bc7\u0bb0\u0bbe\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child flattens upper cuff.", "\u0b95\u0ba3\u0bc1\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bbf\u0bb2\u0bcd \u0b89\u0bb3\u0bcd\u0bb3 \u0b9a\u0bc1\u0bb0\u0bc1\u0b95\u0bcd\u0b95\u0b99\u0bcd\u0b95\u0bb3\u0bc8 \u0ba8\u0bc0\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Straighten the sock around your ankle!", "\u0b95\u0ba3\u0bc1\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bbf\u0bb2\u0bcd \u0ba8\u0bc7\u0bb0\u0bbe\u0b95\u0bcd\u0b95\u0bc1!"),


            StepTuple("Check that the heel is correctly positioned", "\u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bcd \u0b9a\u0bb0\u0bbf\u0baf\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9 \u0b9a\u0bb0\u0bbf\u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child inspects heel placement.", "\u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bcd \u0bb5\u0bb3\u0bc8\u0bb5\u0bc1 \u0b9a\u0bb0\u0bbf\u0baf\u0bbe\u0ba9 \u0b87\u0b9f\u0ba4\u0bcd\u0ba4\u0bbf\u0bb2\u0bcd \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Look at the heel! Fits just right!", "\u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bcd \u0b9a\u0bb0\u0bbf\u0baf\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd!"),


            StepTuple("Repeat the same sequence with the other sock", "\u0bae\u0bb1\u0bcd\u0bb1\u0bca\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0bbf\u0bb2\u0bc1\u0bae\u0bcd \u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0baf\u0bc8 \u0b85\u0bb5\u0bcd\u0bb5\u0bbe\u0bb1\u0bc7 \u0b85\u0ba3\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child repeats steps 2 through 16 for opposite foot.", "\u0bae\u0bb1\u0bcd\u0bb1\u0bca\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0baf\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0b95\u0bbe\u0bb2\u0bbf\u0bb2\u0bcd \u0bb5\u0bb0\u0bbf\u0b9a\u0bc8\u0baf\u0bbe\u0b95 \u0b85\u0ba3\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Now put the second sock on your other foot!", "\u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0baf\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b85\u0ba4\u0bc7\u0baa\u0bcb\u0bb2\u0bcd \u0baa\u0bcb\u0b9f\u0bc1!"),


            StepTuple("Check both socks for correct positioning and comfort", "\u0b87\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0b95\u0bb3\u0bc1\u0bae\u0bcd \u0b9a\u0bb0\u0bbf\u0baf\u0bbe\u0b95\u0bb5\u0bc1\u0bae\u0bcd \u0bb5\u0b9a\u0ba4\u0bbf\u0baf\u0bbe\u0b95\u0bb5\u0bc1\u0bae\u0bcd \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child verifies comfort on both feet.", "\u0b87\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0bcd\u0b95\u0bb3\u0bbf\u0bb2\u0bc1\u0bae\u0bcd \u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0b95\u0bb3\u0bcd \u0bb5\u0b9a\u0ba4\u0bbf\u0baf\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bc8 \u0b89\u0bb1\u0bc1\u0ba4\u0bbf\u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Wiggle your toes! Both socks feel super cozy!", "\u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bc8 \u0b86\u0b9f\u0bcd\u0b9f\u0bbf\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd! \u0b95\u0bbe\u0bb2\u0bc1\u0bb1\u0bc8\u0b95\u0bb3\u0bcd \u0b85\u0bb0\u0bc1\u0bae\u0bc8\u0baf\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba9!"),


        ),


        9L to listOf(


            StepTuple("Sit in a stable position and look at the shoes", "\u0ba8\u0bbf\u0bb2\u0bc8\u0baf\u0bbe\u0b95 \u0b85\u0bae\u0bb0\u0bcd\u0ba8\u0bcd\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bb3\u0bc8\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child sits securely facing pair of shoes.", "\u0b95\u0bc1\u0bb4\u0ba8\u0bcd\u0ba4\u0bc8 \u0ba8\u0bbf\u0bb2\u0bc8\u0baf\u0bbe\u0b95 \u0b85\u0bae\u0bb0\u0bcd\u0ba8\u0bcd\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bb3\u0bc8\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95 \u0bb5\u0bc7\u0ba3\u0bcd\u0b9f\u0bc1\u0bae\u0bcd.", "Sit steady and look at your shoes!", "\u0ba8\u0bbf\u0bb2\u0bc8\u0baf\u0bbe\u0b95 \u0b85\u0bae\u0bb0\u0bcd\u0ba8\u0bcd\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bb3\u0bc8\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd!"),


            StepTuple("Identify the right and left shoe", "\u0bb5\u0bb2\u0ba4\u0bc1 \u0bae\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0b87\u0b9f\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8 \u0b85\u0b9f\u0bc8\u0baf\u0bbe\u0bb3\u0bae\u0bcd \u0b95\u0bbe\u0ba3\u0bb5\u0bc1\u0bae\u0bcd", "Child distinguishes left from right shoe orientation.", "\u0bb5\u0bb2\u0ba4\u0bc1 \u0bae\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0b87\u0b9f\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bb3\u0bc8 \u0b85\u0b9f\u0bc8\u0baf\u0bbe\u0bb3\u0bae\u0bcd \u0b95\u0bbe\u0ba3\u0bb5\u0bc1\u0bae\u0bcd.", "Find the right shoe and the left shoe!", "\u0bb5\u0bb2\u0ba4\u0bc1 \u0bae\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0b87\u0b9f\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bc1\u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Pick up the correct shoe", "\u0b9a\u0bb0\u0bbf\u0baf\u0bbe\u0ba9 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child selects shoe corresponding to chosen foot.", "\u0b85\u0ba3\u0bbf\u0baf \u0bb5\u0bc7\u0ba3\u0bcd\u0b9f\u0bbf\u0baf \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8\u0b95\u0bcd \u0b95\u0bc8\u0baf\u0bbf\u0bb2\u0bcd \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Pick up the shoe for your foot!", "\u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8 \u0b8e\u0b9f\u0bc1!"),


            StepTuple("Identify the front and back of the shoe", "\u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bbf\u0ba9\u0bcd \u0bae\u0bc1\u0ba9\u0bcd\u0baa\u0bc1\u0bb1\u0bae\u0bcd \u0bae\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0baa\u0bbf\u0ba9\u0bcd\u0baa\u0bc1\u0bb1\u0ba4\u0bcd\u0ba4\u0bc8 \u0b85\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child identifies toe box and heel counter.", "\u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bbf\u0ba9\u0bcd \u0bae\u0bc1\u0ba9\u0bcd \u0bae\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0baa\u0bbf\u0ba9\u0bcd \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0baf\u0bc8 \u0b85\u0b9f\u0bc8\u0baf\u0bbe\u0bb3\u0bae\u0bcd \u0b95\u0bbe\u0ba3\u0bb5\u0bc1\u0bae\u0bcd.", "Find the front toes and back heel of the shoe!", "\u0bae\u0bc1\u0ba9\u0bcd \u0bb5\u0bbf\u0bb0\u0bb2\u0bcd \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0baf\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0baa\u0bbf\u0ba9\u0bcd \u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bc1\u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Open the Velcro strap", "\u0bb5\u0bc6\u0bb2\u0bcd\u0b95\u0bcd\u0bb0\u0bcb \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8\u0ba4\u0bcd \u0ba4\u0bbf\u0bb1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child peels velcro strap open with a pull.", "\u0bb5\u0bc6\u0bb2\u0bcd\u0b95\u0bcd\u0bb0\u0bcb \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0b87\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bc1\u0ba4\u0bcd \u0ba4\u0bbf\u0bb1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Pull the velcro strap open! Rrrrrip!", "\u0bb5\u0bc6\u0bb2\u0bcd\u0b95\u0bcd\u0bb0\u0bcb \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0b87\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bc1\u0ba4\u0bcd \u0ba4\u0bbf\u0bb1!"),


            StepTuple("Hold the shoe open", "\u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8 \u0b85\u0b95\u0bb2\u0bae\u0bbe\u0b95\u0ba4\u0bcd \u0ba4\u0bbf\u0bb1\u0ba8\u0bcd\u0ba4\u0bc1 \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child holds collar and tongue forward.", "\u0ba8\u0bbe\u0b95\u0bcd\u0b95\u0bc1\u0baa\u0bcd \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0baf\u0bc8 \u0bae\u0bc1\u0ba9\u0bcd\u0ba9\u0bcb\u0b95\u0bcd\u0b95\u0bbf \u0b87\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bc1 \u0b85\u0b95\u0bb2\u0bae\u0bbe\u0b95\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Hold the shoe open wide!", "\u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8 \u0b85\u0b95\u0bb2\u0bae\u0bbe\u0b95\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Lift the corresponding foot", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0b89\u0baf\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bb5\u0bc1\u0bae\u0bcd", "Child raises foot to shoe opening.", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bbf\u0ba9\u0bcd \u0bae\u0bc1\u0ba9\u0bcd \u0b89\u0baf\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bb5\u0bc1\u0bae\u0bcd.", "Lift your foot up to the shoe!", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0bae\u0bc7\u0bb2\u0bc7 \u0ba4\u0bc2\u0b95\u0bcd\u0b95\u0bc1!"),


            StepTuple("Place the toes into the shoe", "\u0b95\u0bbe\u0bb2\u0bcd \u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bc8 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child inserts toes into front toe box.", "\u0b95\u0bbe\u0bb2\u0bcd \u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bc8 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bbf\u0ba9\u0bcd \u0bae\u0bc1\u0ba9\u0bcd \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Put your toes right into the shoe!", "\u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bc8 \u0b89\u0bb3\u0bcd\u0bb3\u0bc7 \u0bb5\u0bc8!"),


            StepTuple("Slide the foot forward into the shoe", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0bae\u0bc1\u0ba9\u0bcd\u0ba9\u0bcb\u0b95\u0bcd\u0b95\u0bbf \u0ba4\u0bb3\u0bcd\u0bb3\u0bb5\u0bc1\u0bae\u0bcd", "Child slides foot forward towards toe cap.", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0bae\u0bc1\u0ba9\u0bcd\u0ba9\u0bcb\u0b95\u0bcd\u0b95\u0bbf \u0ba8\u0b95\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bb5\u0bc1\u0bae\u0bcd.", "Slide your foot forward!", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0bae\u0bc1\u0ba9\u0bcd\u0ba9\u0bbe\u0bb2\u0bcd \u0ba4\u0bb3\u0bcd\u0bb3\u0bc1!"),


            StepTuple("Push the heel down into the shoe", "\u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bc8 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0b95\u0bc0\u0bb4\u0bc7 \u0b85\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bb5\u0bc1\u0bae\u0bcd", "Child presses heel down firmly into shoe bed.", "\u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bc8 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bbf\u0ba9\u0bcd \u0ba4\u0bb0\u0bc8\u0baa\u0bcd\u0baa\u0b95\u0bc1\u0ba4\u0bbf \u0bb5\u0bb0\u0bc8 \u0b95\u0bc0\u0bb4\u0bc7 \u0b85\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bb5\u0bc1\u0bae\u0bcd.", "Push your heel all the way down!", "\u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bc8 \u0b95\u0bc0\u0bb4\u0bc7 \u0b85\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bc1!"),


            StepTuple("Check that the heel is inside the shoe", "\u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bcd \u0bae\u0bc1\u0bb4\u0bc1\u0bae\u0bc8\u0baf\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0bc7 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9 \u0b9a\u0bb0\u0bbf\u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child verifies heel is fully nested.", "\u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bcd \u0bae\u0bc1\u0bb4\u0bc1\u0bae\u0bc8\u0baf\u0bbe\u0b95 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Make sure your heel is all the way in!", "\u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bcd \u0b89\u0bb3\u0bcd\u0bb3\u0bc7 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd!"),


            StepTuple("Adjust the foot so that it is positioned comfortably", "\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0bb5\u0b9a\u0ba4\u0bbf\u0baf\u0bbe\u0b95 \u0b87\u0bb0\u0bc1\u0b95\u0bcd\u0b95\u0bc1\u0bae\u0bbe\u0bb1\u0bc1 \u0b9a\u0bb0\u0bbf\u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child wiggles foot into aligned position.", "\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0bb5\u0bb2\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bae\u0bb2\u0bcd \u0bb5\u0b9a\u0ba4\u0bbf\u0baf\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9 \u0b9a\u0bb0\u0bbf\u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Wiggle your foot so it feels comfortable!", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0bb5\u0b9a\u0ba4\u0bbf\u0baf\u0bbe\u0b95 \u0b9a\u0bb0\u0bbf\u0b9a\u0bc6\u0baf\u0bcd!"),


            StepTuple("Pull the Velcro strap across the top of the foot", "\u0bb5\u0bc6\u0bb2\u0bcd\u0b95\u0bcd\u0bb0\u0bcb \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bbf\u0ba9\u0bcd \u0bae\u0bc7\u0bb2\u0bcd \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child pulls strap across instep tightly.", "\u0bb5\u0bc6\u0bb2\u0bcd\u0b95\u0bcd\u0bb0\u0bcb \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bbf\u0ba9\u0bcd \u0b95\u0bc1\u0bb1\u0bc1\u0b95\u0bcd\u0b95\u0bc7 \u0b87\u0bb1\u0bc1\u0b95\u0bcd\u0b95\u0bae\u0bbe\u0b95 \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Pull the velcro strap tight across your foot!", "\u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0b95\u0bc1\u0bb1\u0bc1\u0b95\u0bcd\u0b95\u0bc7 \u0b87\u0bb4\u0bc1!"),


            StepTuple("Press the Velcro strap down firmly", "\u0bb5\u0bc6\u0bb2\u0bcd\u0b95\u0bcd\u0bb0\u0bcb \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0b89\u0bb1\u0bc1\u0ba4\u0bbf\u0baf\u0bbe\u0b95 \u0b85\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bb5\u0bc1\u0bae\u0bcd", "Child presses velcro hook-and-loop together.", "\u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0ba8\u0ba9\u0bcd\u0bb1\u0bbe\u0b95 \u0b85\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bbf \u0b92\u0b9f\u0bcd\u0b9f \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Press the velcro strap down firm!", "\u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0b85\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bbf \u0b92\u0b9f\u0bcd\u0b9f\u0bc1!"),


            StepTuple("Check that the shoe is secure", "\u0b95\u0bbe\u0bb2\u0ba3\u0bbf \u0b95\u0bbe\u0bb2\u0bbf\u0bb2\u0bcd \u0b89\u0bb1\u0bc1\u0ba4\u0bbf\u0baf\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9 \u0b9a\u0bb0\u0bbf\u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child tugs gently to ensure strap holds.", "\u0b95\u0bbe\u0bb2\u0ba3\u0bbf \u0b95\u0bb4\u0ba9\u0bcd\u0bb1\u0bc1 \u0bb5\u0bbf\u0b9f\u0bbe\u0bae\u0bb2\u0bcd \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9 \u0b89\u0bb1\u0bc1\u0ba4\u0bbf\u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Make sure the shoe is on tight!", "\u0b95\u0bbe\u0bb2\u0ba3\u0bbf \u0b89\u0bb1\u0bc1\u0ba4\u0bbf\u0baf\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd!"),


            StepTuple("Repeat the same sequence with the other shoe", "\u0bae\u0bb1\u0bcd\u0bb1\u0bca\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b85\u0bb5\u0bcd\u0bb5\u0bbe\u0bb1\u0bc7 \u0b85\u0ba3\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child repeats procedure for second foot.", "\u0bae\u0bb1\u0bcd\u0bb1\u0bca\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0b95\u0bbe\u0bb2\u0bbf\u0bb2\u0bcd \u0bb5\u0bb0\u0bbf\u0b9a\u0bc8\u0baf\u0bbe\u0b95 \u0b85\u0ba3\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Now put on your other shoe the same way!", "\u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b85\u0ba4\u0bc7\u0baa\u0bcb\u0bb2\u0bcd \u0baa\u0bcb\u0b9f\u0bc1!"),


            StepTuple("Check that both shoes are correctly positioned and stand up safely", "\u0b87\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bb3\u0bc1\u0bae\u0bcd \u0b9a\u0bb0\u0bbf\u0baf\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bc1 \u0b8e\u0bb4\u0bc1\u0ba8\u0bcd\u0ba4\u0bc1 \u0ba8\u0bbf\u0bb1\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child stands up safely and tests balance.", "\u0baa\u0bbe\u0ba4\u0bc1\u0b95\u0bbe\u0baa\u0bcd\u0baa\u0bbe\u0b95 \u0b8e\u0bb4\u0bc1\u0ba8\u0bcd\u0ba4\u0bc1 \u0ba8\u0bbf\u0ba9\u0bcd\u0bb1\u0bc1 \u0b87\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bb3\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Stand up tall and steady on both feet!", "\u0b8e\u0bb4\u0bc1\u0ba8\u0bcd\u0ba4\u0bc1 \u0ba8\u0bc7\u0bb0\u0bbe\u0b95 \u0ba8\u0bbf\u0bb2\u0bcd!"),


            StepTuple("Check that both shoes feel comfortable and secure", "\u0b87\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bb3\u0bc1\u0bae\u0bcd \u0bb5\u0b9a\u0ba4\u0bbf\u0baf\u0bbe\u0b95\u0bb5\u0bc1\u0bae\u0bcd \u0b9a\u0bb0\u0bbf\u0baf\u0bbe\u0b95\u0bb5\u0bc1\u0bae\u0bcd \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9 \u0b89\u0bb1\u0bc1\u0ba4\u0bbf\u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child takes test steps.", "\u0ba8\u0b9f\u0ba8\u0bcd\u0ba4\u0bc1 \u0baa\u0bbe\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bc1 \u0b87\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bb3\u0bc1\u0bae\u0bcd \u0bb5\u0b9a\u0ba4\u0bbf\u0baf\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bc8 \u0b89\u0bb1\u0bc1\u0ba4\u0bbf\u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Stomp your feet! You are ready to walk and play!", "\u0b95\u0bc1\u0ba4\u0bbf\u0ba4\u0bcd\u0ba4\u0bc1\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd! \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bb3\u0bcd \u0b9a\u0bc2\u0baa\u0bcd\u0baa\u0bb0\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba9!"),


        ),


        10L to listOf(


            StepTuple("Sit in a stable position", "\u0ba8\u0bbf\u0bb2\u0bc8\u0baf\u0bbe\u0b95 \u0b85\u0bae\u0bb0\u0bb5\u0bc1\u0bae\u0bcd", "Child sits securely.", "\u0b95\u0bc1\u0bb4\u0ba8\u0bcd\u0ba4\u0bc8 \u0ba8\u0bbf\u0bb2\u0bc8\u0baf\u0bbe\u0b95 \u0b85\u0bae\u0bb0 \u0bb5\u0bc7\u0ba3\u0bcd\u0b9f\u0bc1\u0bae\u0bcd.", "Sit nice and steady!", "\u0ba8\u0bbf\u0bb2\u0bc8\u0baf\u0bbe\u0b95 \u0b85\u0bae\u0bb0\u0bcd\u0ba8\u0bcd\u0ba4\u0bc1 \u0b95\u0bca\u0bb3\u0bcd!"),


            StepTuple("Identify the right and left shoe", "\u0bb5\u0bb2\u0ba4\u0bc1 \u0bae\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0b87\u0b9f\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8 \u0b85\u0b9f\u0bc8\u0baf\u0bbe\u0bb3\u0bae\u0bcd \u0b95\u0bbe\u0ba3\u0bb5\u0bc1\u0bae\u0bcd", "Child distinguishes right and left shoe.", "\u0bb5\u0bb2\u0ba4\u0bc1 \u0bae\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0b87\u0b9f\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bb3\u0bc8 \u0b85\u0b9f\u0bc8\u0baf\u0bbe\u0bb3\u0bae\u0bcd \u0b95\u0bbe\u0ba3\u0bb5\u0bc1\u0bae\u0bcd.", "Find the right shoe and the left shoe!", "\u0bb5\u0bb2\u0ba4\u0bc1 \u0bae\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0b87\u0b9f\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bc1\u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Pick up the correct shoe", "\u0b9a\u0bb0\u0bbf\u0baf\u0bbe\u0ba9 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child selects appropriate shoe.", "\u0b85\u0ba3\u0bbf\u0baf \u0bb5\u0bc7\u0ba3\u0bcd\u0b9f\u0bbf\u0baf \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Pick up your shoe!", "\u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8 \u0b8e\u0b9f\u0bc1!"),


            StepTuple("Loosen/open the shoelaces sufficiently", "\u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bcd \u0b95\u0baf\u0bbf\u0bb1\u0bc1\u0b95\u0bb3\u0bc8 \u0ba4\u0bb3\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bb5\u0bc1\u0bae\u0bcd", "Child loosens laces and pulls tongue forward.", "\u0b95\u0baf\u0bbf\u0bb1\u0bc1\u0b95\u0bb3\u0bc8 \u0ba4\u0bb3\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bbf \u0ba8\u0bbe\u0b95\u0bcd\u0b95\u0bc1\u0baa\u0bcd \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0baf\u0bc8 \u0bae\u0bc1\u0ba9\u0bcd\u0ba9\u0bcb\u0b95\u0bcd\u0b95\u0bbf \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Loosen up the laces so it opens wide!", "\u0b95\u0baf\u0bbf\u0bb1\u0bc1\u0b95\u0bb3\u0bc8 \u0ba4\u0bb3\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bbf \u0b85\u0b95\u0bb2\u0bae\u0bbe\u0b95\u0bcd\u0b95\u0bc1!"),


            StepTuple("Hold the shoe open", "\u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8\u0ba4\u0bcd \u0ba4\u0bbf\u0bb1\u0ba8\u0bcd\u0ba4\u0bc1 \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child holds collar open.", "\u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bbf\u0ba9\u0bcd \u0ba4\u0bbf\u0bb1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0baf\u0bc8 \u0b85\u0b95\u0bb2\u0bae\u0bbe\u0b95\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Hold the shoe open with both hands!", "\u0b87\u0bb0\u0bc1 \u0b95\u0bc8\u0b95\u0bb3\u0bbe\u0bb2\u0bc1\u0bae\u0bcd \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8\u0ba4\u0bcd \u0ba4\u0bbf\u0bb1\u0ba8\u0bcd\u0ba4\u0bc1 \u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Place the toes into the shoe", "\u0b95\u0bbe\u0bb2\u0bcd \u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bc8 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child slides toes into opening.", "\u0b95\u0bbe\u0bb2\u0bcd \u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bc8 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Put your toes in!", "\u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bc8 \u0b89\u0bb3\u0bcd\u0bb3\u0bc7 \u0bb5\u0bc8!"),


            StepTuple("Slide the foot forward", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0bae\u0bc1\u0ba9\u0bcd\u0ba9\u0bcb\u0b95\u0bcd\u0b95\u0bbf \u0ba4\u0bb3\u0bcd\u0bb3\u0bb5\u0bc1\u0bae\u0bcd", "Child pushes foot forward into toe box.", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0bae\u0bc1\u0ba9\u0bcd\u0ba9\u0bcb\u0b95\u0bcd\u0b95\u0bbf \u0ba8\u0b95\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bb5\u0bc1\u0bae\u0bcd.", "Slide your foot all the way forward!", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0bae\u0bc1\u0ba9\u0bcd\u0ba9\u0bbe\u0bb2\u0bcd \u0ba4\u0bb3\u0bcd\u0bb3\u0bc1!"),


            StepTuple("Push the heel down", "\u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bc8 \u0b95\u0bc0\u0bb4\u0bc7 \u0b85\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bb5\u0bc1\u0bae\u0bcd", "Child pushes heel into rear footbed.", "\u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bc8 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0b95\u0bc0\u0bb4\u0bc7 \u0b85\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bb5\u0bc1\u0bae\u0bcd.", "Push your heel down into the shoe!", "\u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bc8 \u0b95\u0bc0\u0bb4\u0bc7 \u0b85\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bc1!"),


            StepTuple("Adjust the tongue of the shoe", "\u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bbf\u0ba9\u0bcd \u0ba8\u0bbe\u0b95\u0bcd\u0b95\u0bc1\u0baa\u0bcd \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0baf\u0bc8 \u0ba8\u0bc7\u0bb0\u0bbe\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child pulls tongue flat against instep.", "\u0ba8\u0bbe\u0b95\u0bcd\u0b95\u0bc1\u0baa\u0bcd \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0baf\u0bc8 \u0b9a\u0bc1\u0bb0\u0bc1\u0b95\u0bcd\u0b95\u0bae\u0bbf\u0ba9\u0bcd\u0bb1\u0bbf \u0ba8\u0bc7\u0bb0\u0bbe\u0b95 \u0b87\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bc1 \u0bb5\u0bbf\u0b9f\u0bb5\u0bc1\u0bae\u0bcd.", "Pull the tongue straight and flat!", "\u0ba8\u0bbe\u0b95\u0bcd\u0b95\u0bc1\u0baa\u0bcd \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0baf\u0bc8 \u0ba8\u0bc7\u0bb0\u0bbe\u0b95\u0bcd\u0b95\u0bc1!"),


            StepTuple("Pull the laces to adjust the shoe", "\u0b95\u0baf\u0bbf\u0bb1\u0bc1\u0b95\u0bb3\u0bc8 \u0b87\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8 \u0b87\u0bb1\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child pulls criss-cross laces snug.", "\u0b95\u0baf\u0bbf\u0bb1\u0bc1\u0b95\u0bb3\u0bc8 \u0b87\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bc1 \u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0ba8\u0ba9\u0bcd\u0b95\u0bc1 \u0baa\u0bca\u0bb0\u0bc1\u0ba8\u0bcd\u0ba4\u0bc1\u0bae\u0bbe\u0bb1\u0bc1 \u0b87\u0bb1\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Pull the laces snug around your foot!", "\u0b95\u0baf\u0bbf\u0bb1\u0bc1\u0b95\u0bb3\u0bc8 \u0b87\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bc1 \u0b87\u0bb1\u0bc1\u0b95\u0bcd\u0b95\u0bc1!"),


            StepTuple("Tie the shoelaces securely", "\u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bcd \u0b95\u0baf\u0bbf\u0bb1\u0bc1\u0b95\u0bb3\u0bc8 \u0bae\u0bc1\u0b9f\u0bbf\u0b9a\u0bcd\u0b9a\u0bc1\u0baa\u0bcd \u0baa\u0bcb\u0b9f\u0bb5\u0bc1\u0bae\u0bcd", "Child ties knots and loops.", "\u0b95\u0baf\u0bbf\u0bb1\u0bc1\u0b95\u0bb3\u0bc8 \u0b9a\u0bc1\u0bb0\u0bc1\u0b95\u0bcd\u0b95\u0bc1\u0baa\u0bcd \u0baa\u0bcb\u0b9f\u0bcd\u0b9f\u0bc1 \u0bae\u0bc1\u0b9f\u0bbf\u0b9a\u0bcd\u0b9a\u0bc1 \u0b95\u0b9f\u0bcd\u0b9f\u0bb5\u0bc1\u0bae\u0bcd.", "Tie up your laces with a nice knot!", "\u0b95\u0baf\u0bbf\u0bb1\u0bc1\u0b95\u0bb3\u0bc8 \u0bae\u0bc1\u0b9f\u0bbf\u0b9a\u0bcd\u0b9a\u0bc1 \u0baa\u0bcb\u0b9f\u0bc1!"),


            StepTuple("Repeat with the other shoe", "\u0bae\u0bb1\u0bcd\u0bb1\u0bca\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b85\u0bb5\u0bcd\u0bb5\u0bbe\u0bb1\u0bc7 \u0b85\u0ba3\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child puts on second lace-up shoe.", "\u0bae\u0bb1\u0bcd\u0bb1\u0bca\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0b95\u0bbe\u0bb2\u0bbf\u0bb2\u0bcd \u0b85\u0ba3\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Now put on your other lace shoe!", "\u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0baa\u0bcb\u0b9f\u0bc1!"),


            StepTuple("Check that both shoes are comfortable and secure", "\u0b87\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bb3\u0bc1\u0bae\u0bcd \u0bb5\u0b9a\u0ba4\u0bbf\u0baf\u0bbe\u0b95\u0bb5\u0bc1\u0bae\u0bcd \u0b9a\u0bb0\u0bbf\u0baf\u0bbe\u0b95\u0bb5\u0bc1\u0bae\u0bcd \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9 \u0b89\u0bb1\u0bc1\u0ba4\u0bbf\u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child stands and verifies fit.", "\u0b8e\u0bb4\u0bc1\u0ba8\u0bcd\u0ba4\u0bc1 \u0ba8\u0bbf\u0ba9\u0bcd\u0bb1\u0bc1 \u0b87\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bb3\u0bc1\u0bae\u0bcd \u0bb5\u0b9a\u0ba4\u0bbf\u0baf\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bc8 \u0b89\u0bb1\u0bc1\u0ba4\u0bbf\u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Laced up tight and ready to run!", "\u0b95\u0baf\u0bbf\u0bb1\u0bc1 \u0b95\u0b9f\u0bcd\u0b9f\u0bbf\u0baf\u0bbe\u0b9a\u0bcd\u0b9a\u0bc1! \u0bb5\u0bbf\u0bb3\u0bc8\u0baf\u0bbe\u0b9f\u0baa\u0bcd \u0baa\u0bcb\u0b95\u0bb2\u0bbe\u0bae\u0bcd!"),


        ),


        11L to listOf(


            StepTuple("Sit upright at the table", "\u0bae\u0bc7\u0b9c\u0bc8\u0baf\u0bbf\u0bb2\u0bcd \u0ba8\u0bc7\u0bb0\u0bbe\u0b95 \u0b85\u0bae\u0bb0\u0bb5\u0bc1\u0bae\u0bcd", "Child takes stable upright posture in chair.", "\u0b95\u0bc1\u0bb4\u0ba8\u0bcd\u0ba4\u0bc8 \u0ba8\u0bbe\u0bb1\u0bcd\u0b95\u0bbe\u0bb2\u0bbf\u0baf\u0bbf\u0bb2\u0bcd \u0bae\u0bc7\u0b9c\u0bc8 \u0bae\u0bc1\u0ba9\u0bcd \u0ba8\u0bc7\u0bb0\u0bbe\u0b95 \u0b85\u0bae\u0bb0 \u0bb5\u0bc7\u0ba3\u0bcd\u0b9f\u0bc1\u0bae\u0bcd.", "Sit up tall and straight at the table!", "\u0bae\u0bc7\u0b9c\u0bc8 \u0bae\u0bc1\u0ba9\u0bcd \u0ba8\u0bc7\u0bb0\u0bbe\u0b95 \u0b85\u0bae\u0bb0\u0bcd\u0ba8\u0bcd\u0ba4\u0bc1 \u0b95\u0bca\u0bb3\u0bcd!"),


            StepTuple("Position the plate within comfortable reach and look at the rice and gravy", "\u0ba4\u0b9f\u0bcd\u0b9f\u0bc8 \u0bb5\u0b9a\u0ba4\u0bbf\u0baf\u0bbe\u0b95 \u0bb5\u0bc8\u0ba4\u0bcd\u0ba4\u0bc1 \u0b89\u0ba3\u0bb5\u0bc8\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child positions food plate within forearm reach.", "\u0ba4\u0b9f\u0bcd\u0b9f\u0bc8 \u0b95\u0bc8\u0b95\u0bb3\u0bc1\u0b95\u0bcd\u0b95\u0bc1 \u0b8e\u0b9f\u0bcd\u0b9f\u0bc1\u0bae\u0bcd \u0ba4\u0bc2\u0bb0\u0ba4\u0bcd\u0ba4\u0bbf\u0bb2\u0bcd \u0bb5\u0bc8\u0ba4\u0bcd\u0ba4\u0bc1 \u0b89\u0ba3\u0bb5\u0bc8\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Put your plate in front of you and look at the yummy food!", "\u0ba4\u0b9f\u0bcd\u0b9f\u0bc8 \u0b8e\u0b9f\u0bcd\u0b9f\u0bc1\u0bae\u0bcd \u0ba4\u0bc2\u0bb0\u0ba4\u0bcd\u0ba4\u0bbf\u0bb2\u0bcd \u0bb5\u0bc8\u0ba4\u0bcd\u0ba4\u0bc1\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd!"),


            StepTuple("Take an appropriate amount of rice using the fingers", "\u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bbe\u0bb2\u0bcd \u0ba4\u0bc7\u0bb5\u0bc8\u0baf\u0bbe\u0ba9 \u0b85\u0bb3\u0bb5\u0bc1 \u0b9a\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child uses fingers to gather small mound of rice.", "\u0b95\u0bc8 \u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bbe\u0bb2\u0bcd \u0b92\u0bb0\u0bc1 \u0baa\u0bbf\u0b9f\u0bbf \u0b9a\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0ba4\u0ba9\u0bbf\u0baf\u0bbe\u0b95 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Gather a small portion of rice with your fingers!", "\u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bbe\u0bb2\u0bcd \u0b95\u0bca\u0b9e\u0bcd\u0b9a\u0bae\u0bcd \u0b9a\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0b8e\u0b9f\u0bc1!"),


            StepTuple("Add an appropriate amount of gravy/curry", "\u0ba4\u0bc7\u0bb5\u0bc8\u0baf\u0bbe\u0ba9 \u0b85\u0bb3\u0bb5\u0bc1 \u0b95\u0bc1\u0bb4\u0bae\u0bcd\u0baa\u0bc8\u0b9a\u0bcd \u0b9a\u0bc7\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child pulls curry over to the rice portion.", "\u0ba4\u0bc7\u0bb5\u0bc8\u0baf\u0bbe\u0ba9 \u0b85\u0bb3\u0bb5\u0bc1 \u0b95\u0bc1\u0bb4\u0bae\u0bcd\u0baa\u0bc8 \u0b85\u0ba8\u0bcd\u0ba4 \u0b9a\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bcb\u0b9f\u0bc1 \u0b9a\u0bc7\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Mix a little bit of gravy into your rice!", "\u0b95\u0bca\u0b9e\u0bcd\u0b9a\u0bae\u0bcd \u0b95\u0bc1\u0bb4\u0bae\u0bcd\u0baa\u0bc8 \u0b9a\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bbf\u0bb2\u0bcd \u0b9a\u0bc7\u0bb0\u0bcd!"),


            StepTuple("Mix the rice and gravy using the fingers", "\u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bbe\u0bb2\u0bcd \u0b9a\u0bbe\u0ba4\u0bae\u0bc1\u0bae\u0bcd \u0b95\u0bc1\u0bb4\u0bae\u0bcd\u0baa\u0bc1\u0bae\u0bcd \u0baa\u0bbf\u0b9a\u0bc8\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child uses fingers to blend rice and gravy together.", "\u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bbe\u0bb2\u0bcd \u0b9a\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b95\u0bc1\u0bb4\u0bae\u0bcd\u0baa\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0ba8\u0ba9\u0bcd\u0bb1\u0bbe\u0b95\u0baa\u0bcd \u0baa\u0bbf\u0b9a\u0bc8\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Mix the rice and gravy nicely together!", "\u0b9a\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b95\u0bc1\u0bb4\u0bae\u0bcd\u0baa\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0baa\u0bbf\u0b9a\u0bc8!"),


            StepTuple("Gather an appropriate-sized portion of the mixed rice", "\u0baa\u0bbf\u0b9a\u0bc8\u0ba8\u0bcd\u0ba4 \u0b9a\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0bb5\u0bbe\u0baf\u0bcd \u0b85\u0bb3\u0bb5\u0bbf\u0bb1\u0bcd\u0b95\u0bc1 \u0b89\u0bb0\u0bc1\u0b9f\u0bcd\u0b9f\u0bb5\u0bc1\u0bae\u0bcd", "Child gathers a bite-sized portion.", "\u0b92\u0bb0\u0bc1 \u0bb5\u0bbe\u0baf\u0bcd \u0b85\u0bb3\u0bb5\u0bbf\u0bb1\u0bcd\u0b95\u0bc1 \u0ba4\u0bc7\u0bb5\u0bc8\u0baf\u0bbe\u0ba9 \u0b9a\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bbe\u0bb2\u0bcd \u0b92\u0ba9\u0bcd\u0bb1\u0bbe\u0b95\u0b9a\u0bcd \u0b9a\u0bc7\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Gather a nice bite-sized portion!", "\u0b92\u0bb0\u0bc1 \u0bb5\u0bbe\u0baf\u0bcd \u0b85\u0bb3\u0bb5\u0bc1 \u0b9a\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0b8e\u0b9f\u0bc1!"),


            StepTuple("Shape/gather the food using the fingers and palm as appropriate", "\u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bbe\u0bb2\u0bcd \u0b9a\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0b89\u0bb0\u0bc1\u0b9f\u0bcd\u0b9f\u0bbf\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child shapes portion into manageable morsel.", "\u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bbf\u0ba9\u0bcd \u0b89\u0ba4\u0bb5\u0bbf\u0baf\u0bc1\u0b9f\u0ba9\u0bcd \u0b9a\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0b9a\u0bbf\u0bb1\u0bbf\u0baf \u0b89\u0bb0\u0bc1\u0ba3\u0bcd\u0b9f\u0bc8\u0baf\u0bbe\u0b95 \u0b89\u0bb0\u0bc1\u0b9f\u0bcd\u0b9f\u0bb5\u0bc1\u0bae\u0bcd.", "Shape it into a neat little bite with your fingers!", "\u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bbe\u0bb2\u0bcd \u0b9a\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0b89\u0bb0\u0bc1\u0ba3\u0bcd\u0b9f\u0bc8 \u0b9a\u0bc6\u0baf\u0bcd!"),


            StepTuple("Bring the food toward the mouth and open the mouth", "\u0b89\u0ba3\u0bb5\u0bc8 \u0bb5\u0bbe\u0baf\u0bbf\u0ba9\u0bcd \u0b85\u0bb0\u0bc1\u0b95\u0bbf\u0bb2\u0bcd \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0bc1 \u0bb5\u0ba8\u0bcd\u0ba4\u0bc1 \u0bb5\u0bbe\u0baf\u0bc8\u0ba4\u0bcd \u0ba4\u0bbf\u0bb1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child moves hand smoothly to open mouth.", "\u0b89\u0ba3\u0bb5\u0bc8 \u0bb5\u0bbe\u0baf\u0bbf\u0ba9\u0bcd \u0b85\u0bb0\u0bc1\u0b95\u0bbf\u0bb2\u0bcd \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0bc1 \u0bb5\u0ba8\u0bcd\u0ba4\u0bc1 \u0bb5\u0bbe\u0baf\u0bc8 \u0b85\u0b95\u0bb2\u0ba4\u0bcd \u0ba4\u0bbf\u0bb1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Bring the food to your mouth and open wide! Ahh!", "\u0b89\u0ba3\u0bb5\u0bc8 \u0bb5\u0bbe\u0baf\u0bb0\u0bc1\u0b95\u0bc7 \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0bc1 \u0bb5\u0bbe! \u0bb5\u0bbe\u0baf\u0bc8\u0ba4\u0bcd \u0ba4\u0bbf\u0bb1! \u0b86!"),


            StepTuple("Place the food into the mouth and move the hand away from the mouth", "\u0b89\u0ba3\u0bb5\u0bc8 \u0bb5\u0bbe\u0baf\u0bbf\u0bb2\u0bcd \u0bb5\u0bc8\u0ba4\u0bcd\u0ba4\u0bc1 \u0b95\u0bc8\u0baf\u0bc8 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child deposits food using thumb push without touching lips with whole palm.", "\u0b89\u0ba3\u0bb5\u0bc8 \u0bb5\u0bbe\u0baf\u0bcd\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0bb5\u0bc8\u0ba4\u0bcd\u0ba4\u0bc1 \u0b95\u0bc8\u0baf\u0bc8 \u0bb5\u0bbe\u0baf\u0bbf\u0bb2\u0bbf\u0bb0\u0bc1\u0ba8\u0bcd\u0ba4\u0bc1 \u0b85\u0b95\u0bb1\u0bcd\u0bb1\u0bb5\u0bc1\u0bae\u0bcd.", "Put the food in your mouth and move your hand back!", "\u0b89\u0ba3\u0bb5\u0bc8 \u0bb5\u0bbe\u0baf\u0bbf\u0bb2\u0bcd \u0bb5\u0bc8\u0ba4\u0bcd\u0ba4\u0bc1 \u0b95\u0bc8\u0baf\u0bc8 \u0b8e\u0b9f\u0bc1!"),


            StepTuple("Chew and swallow the food", "\u0b89\u0ba3\u0bb5\u0bc8 \u0bae\u0bc6\u0ba9\u0bcd\u0bb1\u0bc1 \u0bb5\u0bbf\u0bb4\u0bc1\u0b99\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child closes mouth, chews thoroughly, and swallows.", "\u0bb5\u0bbe\u0baf\u0bc8 \u0bae\u0bc2\u0b9f\u0bbf \u0b89\u0ba3\u0bb5\u0bc8 \u0ba8\u0ba9\u0bcd\u0bb1\u0bbe\u0b95 \u0bae\u0bc6\u0ba9\u0bcd\u0bb1\u0bc1 \u0bb5\u0bbf\u0bb4\u0bc1\u0b99\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Chew your food nicely and swallow!", "\u0ba8\u0ba9\u0bcd\u0bb1\u0bbe\u0b95 \u0bae\u0bc6\u0ba9\u0bcd\u0bb1\u0bc1 \u0bb5\u0bbf\u0bb4\u0bc1\u0b99\u0bcd\u0b95\u0bc1!"),


            StepTuple("Return the hand to the plate", "\u0b95\u0bc8\u0baf\u0bc8 \u0bae\u0bc0\u0ba3\u0bcd\u0b9f\u0bc1\u0bae\u0bcd \u0ba4\u0b9f\u0bcd\u0b9f\u0bbf\u0bb1\u0bcd\u0b95\u0bc1 \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0bc1 \u0bb5\u0bb0\u0bb5\u0bc1\u0bae\u0bcd", "Child rests hand back near plate.", "\u0b95\u0bc8\u0baf\u0bc8 \u0bae\u0bc0\u0ba3\u0bcd\u0b9f\u0bc1\u0bae\u0bcd \u0ba4\u0b9f\u0bcd\u0b9f\u0bbf\u0ba9\u0bcd \u0baa\u0b95\u0bcd\u0b95\u0bae\u0bcd \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0bc1 \u0bb5\u0bb0\u0bb5\u0bc1\u0bae\u0bcd.", "Bring your hand back down to your plate!", "\u0b95\u0bc8\u0baf\u0bc8 \u0ba4\u0b9f\u0bcd\u0b9f\u0bbf\u0ba9\u0bcd \u0baa\u0b95\u0bcd\u0b95\u0bae\u0bcd \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0bc1 \u0bb5\u0bbe!"),


            StepTuple("Repeat the sequence with the next portion", "\u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0baa\u0bbf\u0b9f\u0bbf \u0b89\u0ba3\u0bb5\u0bbf\u0bb1\u0bcd\u0b95\u0bc1\u0bae\u0bcd \u0b85\u0bb5\u0bcd\u0bb5\u0bbe\u0bb1\u0bc7 \u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child gathers subsequent bite.", "\u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0baa\u0bbf\u0b9f\u0bbf \u0b9a\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b95\u0bc1\u0bb4\u0bae\u0bcd\u0baa\u0bc1\u0b9f\u0ba9\u0bcd \u0b9a\u0bc7\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bc1 \u0baa\u0bbf\u0b9a\u0bc8\u0ba8\u0bcd\u0ba4\u0bc1 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Now gather your next yummy bite!", "\u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0baa\u0bbf\u0b9f\u0bbf \u0b9a\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0b8e\u0b9f\u0bc1!"),


            StepTuple("Continue until the appropriate amount of food is eaten", "\u0baa\u0bcb\u0ba4\u0bc1\u0bae\u0bbe\u0ba9 \u0b85\u0bb3\u0bb5\u0bc1 \u0b89\u0ba3\u0bb5\u0bc1 \u0b9a\u0bbe\u0baa\u0bcd\u0baa\u0bbf\u0b9f\u0bc1\u0bae\u0bcd \u0bb5\u0bb0\u0bc8 \u0ba4\u0bca\u0b9f\u0bb0\u0bb5\u0bc1\u0bae\u0bcd", "Child continues eating self-paced meal.", "\u0bb5\u0baf\u0bbf\u0bb1\u0bc1 \u0ba8\u0bbf\u0bb1\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0bb5\u0bb0\u0bc8 \u0bae\u0bc1\u0bb1\u0bc8\u0baf\u0bbe\u0b95 \u0b9a\u0bbe\u0baa\u0bcd\u0baa\u0bbf\u0b9f\u0bcd\u0b9f\u0bc1 \u0bae\u0bc1\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Keep eating until your tummy is happy and full!", "\u0bb5\u0baf\u0bbf\u0bb1\u0bc1 \u0ba8\u0bbf\u0bb1\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0bb5\u0bb0\u0bc8 \u0b9a\u0bbe\u0baa\u0bcd\u0baa\u0bbf\u0b9f\u0bc1!"),


            StepTuple("Wipe/clean the hands", "\u0b95\u0bc8\u0b95\u0bb3\u0bc8\u0ba4\u0bcd \u0ba4\u0bc1\u0b9f\u0bc8\u0ba4\u0bcd\u0ba4\u0bc1 \u0b9a\u0bc1\u0ba4\u0bcd\u0ba4\u0bae\u0bcd \u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child washes or wipes fingers with napkin.", "\u0b9a\u0bbe\u0baa\u0bcd\u0baa\u0bbf\u0b9f\u0bcd\u0b9f\u0bc1 \u0bae\u0bc1\u0b9f\u0bbf\u0ba4\u0bcd\u0ba4\u0ba4\u0bc1\u0bae\u0bcd \u0b95\u0bc8\u0b95\u0bb3\u0bc8\u0ba4\u0bcd \u0ba4\u0bc1\u0b9f\u0bc8\u0ba4\u0bcd\u0ba4\u0bc1 \u0b95\u0bb4\u0bc1\u0bb5\u0bb5\u0bc1\u0bae\u0bcd.", "Clean your hands with water and a towel! All done!", "\u0b95\u0bc8\u0b95\u0bb3\u0bc8 \u0ba8\u0ba9\u0bcd\u0bb1\u0bbe\u0b95\u0b95\u0bcd \u0b95\u0bb4\u0bc1\u0bb5\u0bbf\u0ba4\u0bcd \u0ba4\u0bc1\u0b9f\u0bc8\u0ba4\u0bcd\u0ba4\u0bc1 \u0bb5\u0bbf\u0b9f\u0bc1! \u0b85\u0bb0\u0bc1\u0bae\u0bc8!"),


        ),


        12L to listOf(


            StepTuple("Position the plate within comfortable reach and look at the breakfast item", "\u0ba4\u0b9f\u0bcd\u0b9f\u0bc8 \u0bb5\u0b9a\u0ba4\u0bbf\u0baf\u0bbe\u0b95 \u0bb5\u0bc8\u0ba4\u0bcd\u0ba4\u0bc1 \u0b9a\u0bbf\u0bb1\u0bcd\u0bb1\u0bc1\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child sits upright facing idli/dosa/roti.", "\u0b95\u0bc1\u0bb4\u0ba8\u0bcd\u0ba4\u0bc8 \u0ba8\u0bc7\u0bb0\u0bbe\u0b95 \u0b85\u0bae\u0bb0\u0bcd\u0ba8\u0bcd\u0ba4\u0bc1 \u0ba4\u0b9f\u0bcd\u0b9f\u0bbf\u0bb2\u0bcd \u0b89\u0bb3\u0bcd\u0bb3 \u0b87\u0b9f\u0bcd\u0bb2\u0bbf, \u0ba4\u0bcb\u0b9a\u0bc8\u0baf\u0bc8\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95 \u0bb5\u0bc7\u0ba3\u0bcd\u0b9f\u0bc1\u0bae\u0bcd.", "Sit upright and look at your delicious breakfast!", "\u0ba8\u0bc7\u0bb0\u0bbe\u0b95 \u0b85\u0bae\u0bb0\u0bcd\u0ba8\u0bcd\u0ba4\u0bc1 \u0b9a\u0bbf\u0bb1\u0bcd\u0bb1\u0bc1\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd!"),


            StepTuple("Reach toward the food with the preferred hand", "\u0bb5\u0bbf\u0bb0\u0bc1\u0baa\u0bcd\u0baa\u0bae\u0bbe\u0ba9 \u0b95\u0bc8\u0baf\u0bbe\u0bb2\u0bcd \u0b89\u0ba3\u0bb5\u0bc8 \u0ba8\u0bcb\u0b95\u0bcd\u0b95\u0bbf \u0ba8\u0bc0\u0b9f\u0bcd\u0b9f\u0bb5\u0bc1\u0bae\u0bcd", "Child extends preferred eating hand.", "\u0b9a\u0bbe\u0baa\u0bcd\u0baa\u0bbf\u0b9f\u0bc1\u0bae\u0bcd \u0b95\u0bc8\u0baf\u0bc8 \u0b89\u0ba3\u0bb5\u0bc1 \u0ba4\u0b9f\u0bcd\u0b9f\u0bc8 \u0ba8\u0bcb\u0b95\u0bcd\u0b95\u0bbf \u0ba8\u0bc0\u0b9f\u0bcd\u0b9f\u0bb5\u0bc1\u0bae\u0bcd.", "Reach your hand toward the food!", "\u0b95\u0bc8\u0baf\u0bc8 \u0ba4\u0b9f\u0bcd\u0b9f\u0bbf\u0ba9\u0bcd \u0baa\u0b95\u0bcd\u0b95\u0bae\u0bcd \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0bc1 \u0bb5\u0bbe!"),


            StepTuple("Pick up the food or an appropriate portion", "\u0b89\u0ba3\u0bb5\u0bbf\u0ba9\u0bcd \u0b92\u0bb0\u0bc1 \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0baf\u0bc8 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child grasps edge of breakfast food.", "\u0b89\u0ba3\u0bb5\u0bbf\u0ba9\u0bcd \u0b92\u0bb0\u0bc1 \u0bb5\u0bbf\u0bb3\u0bbf\u0bae\u0bcd\u0baa\u0bc8 \u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bbe\u0bb2\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Pick up a piece of the food!", "\u0b89\u0ba3\u0bb5\u0bbf\u0ba9\u0bcd \u0b92\u0bb0\u0bc1 \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0baf\u0bc8 \u0b8e\u0b9f\u0bc1!"),


            StepTuple("Break the food into a manageable-sized piece when required", "\u0b89\u0ba3\u0bb5\u0bc8 \u0ba4\u0bc7\u0bb5\u0bc8\u0baf\u0bbe\u0ba9 \u0b9a\u0bbf\u0bb1\u0bbf\u0baf \u0ba4\u0bc1\u0ba3\u0bcd\u0b9f\u0bbe\u0b95\u0baa\u0bcd \u0baa\u0bbf\u0baf\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child uses fingers to tear off bite-sized morsel.", "\u0b95\u0bc8 \u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bbe\u0bb2\u0bcd \u0b92\u0bb0\u0bc1 \u0bb5\u0bbe\u0baf\u0bcd \u0b85\u0bb3\u0bb5\u0bbf\u0bb1\u0bcd\u0b95\u0bc1 \u0b89\u0ba3\u0bb5\u0bc8\u0baa\u0bcd \u0baa\u0bbf\u0baf\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Tear off a small bite-sized piece!", "\u0b9a\u0bbf\u0bb1\u0bbf\u0baf \u0ba4\u0bc1\u0ba3\u0bcd\u0b9f\u0bbe\u0b95\u0baa\u0bcd \u0baa\u0bbf\u0baf\u0bcd!"),


            StepTuple("Hold the food securely using the fingers", "\u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bbe\u0bb2\u0bcd \u0b89\u0ba3\u0bb5\u0bc8 \u0b89\u0bb1\u0bc1\u0ba4\u0bbf\u0baf\u0bbe\u0b95\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child secures piece between thumb and fingers.", "\u0baa\u0bbf\u0baf\u0bcd\u0ba4\u0bcd\u0ba4 \u0b89\u0ba3\u0bb5\u0bc8 \u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bc1\u0b95\u0bcd\u0b95\u0bc1 \u0b87\u0b9f\u0bc8\u0baf\u0bc7 \u0b95\u0bc6\u0b9f\u0bcd\u0b9f\u0bbf\u0baf\u0bbe\u0b95\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Hold the piece securely with your fingers!", "\u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bbe\u0bb2\u0bcd \u0b89\u0ba3\u0bb5\u0bc8\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Add or dip into an appropriate accompaniment such as chutney or sambar, when applicable", "\u0b9a\u0b9f\u0bcd\u0ba9\u0bbf \u0b85\u0bb2\u0bcd\u0bb2\u0ba4\u0bc1 \u0b9a\u0bbe\u0bae\u0bcd\u0baa\u0bbe\u0bb0\u0bbf\u0bb2\u0bcd \u0ba4\u0bca\u0b9f\u0bcd\u0b9f\u0bc1 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child dips food lightly into chutney/sambar.", "\u0b89\u0ba3\u0bb5\u0bc8 \u0b9a\u0b9f\u0bcd\u0ba9\u0bbf \u0b85\u0bb2\u0bcd\u0bb2\u0ba4\u0bc1 \u0b9a\u0bbe\u0bae\u0bcd\u0baa\u0bbe\u0bb0\u0bbf\u0bb2\u0bcd \u0ba4\u0bca\u0b9f\u0bcd\u0b9f\u0bc1 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Dip your food into the yummy chutney or sambar!", "\u0b9a\u0b9f\u0bcd\u0ba9\u0bbf \u0b85\u0bb2\u0bcd\u0bb2\u0ba4\u0bc1 \u0b9a\u0bbe\u0bae\u0bcd\u0baa\u0bbe\u0bb0\u0bbf\u0bb2\u0bcd \u0ba4\u0bca\u0b9f\u0bc1!"),


            StepTuple("Bring the food toward the mouth and open the mouth", "\u0b89\u0ba3\u0bb5\u0bc8 \u0bb5\u0bbe\u0baf\u0bb0\u0bc1\u0b95\u0bc7 \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0bc1 \u0bb5\u0ba8\u0bcd\u0ba4\u0bc1 \u0bb5\u0bbe\u0baf\u0bc8\u0ba4\u0bcd \u0ba4\u0bbf\u0bb1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child transports food to open mouth.", "\u0b89\u0ba3\u0bb5\u0bc8 \u0bb5\u0bbe\u0baf\u0bbf\u0ba9\u0bcd \u0b85\u0bb0\u0bc1\u0b95\u0bbf\u0bb2\u0bcd \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0bc1 \u0bb5\u0ba8\u0bcd\u0ba4\u0bc1 \u0bb5\u0bbe\u0baf\u0bc8\u0ba4\u0bcd \u0ba4\u0bbf\u0bb1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Bring the food to your mouth and open wide! Ahh!", "\u0b89\u0ba3\u0bb5\u0bc8 \u0bb5\u0bbe\u0baf\u0bb0\u0bc1\u0b95\u0bc7 \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0bc1 \u0bb5\u0bbe! \u0bb5\u0bbe\u0baf\u0bc8\u0ba4\u0bcd \u0ba4\u0bbf\u0bb1!"),


            StepTuple("Place the food into the mouth", "\u0b89\u0ba3\u0bb5\u0bc8 \u0bb5\u0bbe\u0baf\u0bcd\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child places food onto tongue.", "\u0b89\u0ba3\u0bb5\u0bc8 \u0bb5\u0bbe\u0baf\u0bcd\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0bae\u0bc6\u0ba4\u0bc1\u0bb5\u0bbe\u0b95 \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Put the bite into your mouth!", "\u0b89\u0ba3\u0bb5\u0bc8 \u0bb5\u0bbe\u0baf\u0bbf\u0bb2\u0bcd \u0bb5\u0bc8!"),


            StepTuple("Move the hand away from the mouth", "\u0b95\u0bc8\u0baf\u0bc8 \u0bb5\u0bbe\u0baf\u0bbf\u0bb2\u0bbf\u0bb0\u0bc1\u0ba8\u0bcd\u0ba4\u0bc1 \u0b85\u0b95\u0bb1\u0bcd\u0bb1\u0bb5\u0bc1\u0bae\u0bcd", "Child releases food and moves hand down.", "\u0b89\u0ba3\u0bb5\u0bc8 \u0bb5\u0bbe\u0baf\u0bbf\u0bb2\u0bcd \u0bb5\u0bc8\u0ba4\u0bcd\u0ba4\u0ba4\u0bc1\u0bae\u0bcd \u0b95\u0bc8\u0baf\u0bc8 \u0bb5\u0bc6\u0bb3\u0bbf\u0baf\u0bc7 \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0bc1 \u0bb5\u0bb0\u0bb5\u0bc1\u0bae\u0bcd.", "Move your hand away!", "\u0b95\u0bc8\u0baf\u0bc8 \u0bb5\u0bc6\u0bb3\u0bbf\u0baf\u0bc7 \u0b8e\u0b9f\u0bc1!"),


            StepTuple("Chew and swallow the food", "\u0b89\u0ba3\u0bb5\u0bc8 \u0bae\u0bc6\u0ba9\u0bcd\u0bb1\u0bc1 \u0bb5\u0bbf\u0bb4\u0bc1\u0b99\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child chews food well and swallows.", "\u0b89\u0ba3\u0bb5\u0bc8 \u0ba8\u0ba9\u0bcd\u0bb1\u0bbe\u0b95 \u0bae\u0bc6\u0ba9\u0bcd\u0bb1\u0bc1 \u0bb5\u0bbf\u0bb4\u0bc1\u0b99\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Chew, chew, chew, and swallow!", "\u0bae\u0bc6\u0ba9\u0bcd\u0bb1\u0bc1 \u0bb5\u0bbf\u0bb4\u0bc1\u0b99\u0bcd\u0b95\u0bc1!"),


            StepTuple("Return the hand toward the plate", "\u0b95\u0bc8\u0baf\u0bc8 \u0bae\u0bc0\u0ba3\u0bcd\u0b9f\u0bc1\u0bae\u0bcd \u0ba4\u0b9f\u0bcd\u0b9f\u0bbf\u0ba9\u0bcd \u0baa\u0b95\u0bcd\u0b95\u0bae\u0bcd \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0bc1 \u0bb5\u0bb0\u0bb5\u0bc1\u0bae\u0bcd", "Child positions hand for next piece.", "\u0b95\u0bc8\u0baf\u0bc8 \u0bae\u0bc0\u0ba3\u0bcd\u0b9f\u0bc1\u0bae\u0bcd \u0ba4\u0b9f\u0bcd\u0b9f\u0bbf\u0ba9\u0bcd \u0baa\u0b95\u0bcd\u0b95\u0bae\u0bcd \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0bc1 \u0bb5\u0bb0\u0bb5\u0bc1\u0bae\u0bcd.", "Rest your hand by the plate!", "\u0b95\u0bc8\u0baf\u0bc8 \u0ba4\u0b9f\u0bcd\u0b9f\u0bbf\u0ba9\u0bcd \u0baa\u0b95\u0bcd\u0b95\u0bae\u0bcd \u0bb5\u0bc8!"),


            StepTuple("Pick up the next appropriate portion", "\u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0ba4\u0bc1\u0ba3\u0bcd\u0b9f\u0bc1 \u0b89\u0ba3\u0bb5\u0bc8 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child prepares next bite.", "\u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0ba4\u0bc1\u0ba3\u0bcd\u0b9f\u0bc1 \u0b89\u0ba3\u0bb5\u0bc8 \u0baa\u0bbf\u0baf\u0bcd\u0ba4\u0bcd\u0ba4\u0bc1 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Break off the next piece!", "\u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0ba4\u0bc1\u0ba3\u0bcd\u0b9f\u0bc8\u0baa\u0bcd \u0baa\u0bbf\u0baf\u0bcd!"),


            StepTuple("Repeat the sequence until the appropriate amount is eaten", "\u0b9a\u0bbe\u0baa\u0bcd\u0baa\u0bbf\u0b9f\u0bcd\u0b9f\u0bc1 \u0bae\u0bc1\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bc1\u0bae\u0bcd \u0bb5\u0bb0\u0bc8 \u0ba4\u0bca\u0b9f\u0bb0\u0bb5\u0bc1\u0bae\u0bcd", "Child finishes meal self-paced.", "\u0bb5\u0baf\u0bbf\u0bb1\u0bc1 \u0ba8\u0bbf\u0bb1\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0bb5\u0bb0\u0bc8 \u0bae\u0bc1\u0bb1\u0bc8\u0baf\u0bbe\u0b95 \u0b9a\u0bbe\u0baa\u0bcd\u0baa\u0bbf\u0b9f\u0bcd\u0b9f\u0bc1 \u0bae\u0bc1\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Keep eating until your tummy is happy!", "\u0bb5\u0baf\u0bbf\u0bb1\u0bc1 \u0ba8\u0bbf\u0bb1\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0bb5\u0bb0\u0bc8 \u0b9a\u0bbe\u0baa\u0bcd\u0baa\u0bbf\u0b9f\u0bc1!"),


            StepTuple("Clean/wipe the hands", "\u0b95\u0bc8\u0b95\u0bb3\u0bc8\u0ba4\u0bcd \u0ba4\u0bc1\u0b9f\u0bc8\u0ba4\u0bcd\u0ba4\u0bc1 \u0b9a\u0bc1\u0ba4\u0bcd\u0ba4\u0bae\u0bcd \u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child washes or wipes mouth and hands.", "\u0b9a\u0bbe\u0baa\u0bcd\u0baa\u0bbf\u0b9f\u0bcd\u0b9f\u0ba4\u0bc1\u0bae\u0bcd \u0b95\u0bc8\u0b95\u0bb3\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0bb5\u0bbe\u0baf\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b9a\u0bc1\u0ba4\u0bcd\u0ba4\u0bae\u0bbe\u0b95\u0ba4\u0bcd \u0ba4\u0bc1\u0b9f\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Wash and dry your hands! You did wonderful!", "\u0b95\u0bc8\u0b95\u0bb3\u0bc8\u0b95\u0bcd \u0b95\u0bb4\u0bc1\u0bb5\u0bbf\u0ba4\u0bcd \u0ba4\u0bc1\u0b9f\u0bc8\u0ba4\u0bcd\u0ba4\u0bc1 \u0bb5\u0bbf\u0b9f\u0bc1! \u0bae\u0bbf\u0b95 \u0b85\u0bb0\u0bc1\u0bae\u0bc8!"),


        ),


        13L to listOf(


            StepTuple("Sit upright at the table", "\u0bae\u0bc7\u0b9c\u0bc8\u0baf\u0bbf\u0bb2\u0bcd \u0ba8\u0bc7\u0bb0\u0bbe\u0b95 \u0b85\u0bae\u0bb0\u0bb5\u0bc1\u0bae\u0bcd", "Child sits upright with elbows relaxed.", "\u0b95\u0bc1\u0bb4\u0ba8\u0bcd\u0ba4\u0bc8 \u0ba8\u0bbe\u0bb1\u0bcd\u0b95\u0bbe\u0bb2\u0bbf\u0baf\u0bbf\u0bb2\u0bcd \u0bae\u0bc7\u0b9c\u0bc8 \u0bae\u0bc1\u0ba9\u0bcd \u0ba8\u0bc7\u0bb0\u0bbe\u0b95 \u0b85\u0bae\u0bb0 \u0bb5\u0bc7\u0ba3\u0bcd\u0b9f\u0bc1\u0bae\u0bcd.", "Sit up tall and straight at the table!", "\u0bae\u0bc7\u0b9c\u0bc8 \u0bae\u0bc1\u0ba9\u0bcd \u0ba8\u0bc7\u0bb0\u0bbe\u0b95 \u0b85\u0bae\u0bb0\u0bcd\u0ba8\u0bcd\u0ba4\u0bc1 \u0b95\u0bca\u0bb3\u0bcd!"),


            StepTuple("Position the bowl/plate within comfortable reach and look at the food", "\u0b95\u0bbf\u0ba3\u0bcd\u0ba3\u0ba4\u0bcd\u0ba4\u0bc8 \u0bb5\u0b9a\u0ba4\u0bbf\u0baf\u0bbe\u0b95 \u0bb5\u0bc8\u0ba4\u0bcd\u0ba4\u0bc1 \u0b89\u0ba3\u0bb5\u0bc8\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child centers bowl on table and looks at food.", "\u0b89\u0ba3\u0bb5\u0bc1 \u0b89\u0bb3\u0bcd\u0bb3 \u0b95\u0bbf\u0ba3\u0bcd\u0ba3\u0ba4\u0bcd\u0ba4\u0bc8 \u0b8e\u0b9f\u0bcd\u0b9f\u0bc1\u0bae\u0bcd \u0ba4\u0bc2\u0bb0\u0ba4\u0bcd\u0ba4\u0bbf\u0bb2\u0bcd \u0bb5\u0bc8\u0ba4\u0bcd\u0ba4\u0bc1 \u0b89\u0ba3\u0bb5\u0bc8\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Place your bowl in front and look at the food!", "\u0b95\u0bbf\u0ba3\u0bcd\u0ba3\u0ba4\u0bcd\u0ba4\u0bc8 \u0bae\u0bc1\u0ba9\u0bcd\u0ba9\u0bbe\u0bb2\u0bcd \u0bb5\u0bc8\u0ba4\u0bcd\u0ba4\u0bc1\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd!"),


            StepTuple("Pick up the spoon using the preferred hand", "\u0bb5\u0bbf\u0bb0\u0bc1\u0baa\u0bcd\u0baa\u0bae\u0bbe\u0ba9 \u0b95\u0bc8\u0baf\u0bbe\u0bb2\u0bcd \u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child grasps spoon handle.", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0b95\u0bc8\u0baf\u0bbf\u0bb2\u0bcd \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Pick up your spoon!", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0b8e\u0b9f\u0bc1!"),


            StepTuple("Hold the spoon securely", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0b89\u0bb1\u0bc1\u0ba4\u0bbf\u0baf\u0bbe\u0b95\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child establishes palmar or digital grasp on handle.", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bbf\u0ba9\u0bcd \u0b95\u0bc8\u0baa\u0bcd\u0baa\u0bbf\u0b9f\u0bbf\u0baf\u0bc8 \u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bbe\u0bb2\u0bcd \u0b95\u0bc6\u0b9f\u0bcd\u0b9f\u0bbf\u0baf\u0bbe\u0b95\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Hold the spoon handle tight in your hand!", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0b89\u0bb1\u0bc1\u0ba4\u0bbf\u0baf\u0bbe\u0b95\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Bring the spoon toward the food", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0b89\u0ba3\u0bb5\u0bc8 \u0ba8\u0bcb\u0b95\u0bcd\u0b95\u0bbf \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0bc1 \u0bb5\u0bb0\u0bb5\u0bc1\u0bae\u0bcd", "Child moves spoon bowl over dish.", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0b89\u0ba3\u0bb5\u0bc1 \u0b89\u0bb3\u0bcd\u0bb3 \u0b95\u0bbf\u0ba3\u0bcd\u0ba3\u0ba4\u0bcd\u0ba4\u0bc8 \u0ba8\u0bcb\u0b95\u0bcd\u0b95\u0bbf\u0b95\u0bcd \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0bc1 \u0bb5\u0bb0\u0bb5\u0bc1\u0bae\u0bcd.", "Bring the spoon over to your food!", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0b89\u0ba3\u0bb5\u0bbf\u0ba9\u0bcd \u0baa\u0b95\u0bcd\u0b95\u0bae\u0bcd \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0bc1 \u0bb5\u0bbe!"),


            StepTuple("Place the spoon into the food", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0b89\u0ba3\u0bb5\u0bc1\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child lowers bowl of spoon into food.", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bbf\u0ba9\u0bcd \u0b95\u0bc1\u0bb4\u0bbf\u0baf\u0bc8 \u0b89\u0ba3\u0bb5\u0bc1\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0b87\u0bb1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Lower the spoon into the food!", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0b89\u0ba3\u0bb5\u0bc1\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0b87\u0bb1\u0b95\u0bcd\u0b95\u0bc1!"),


            StepTuple("Scoop an appropriate amount of food", "\u0ba4\u0bc7\u0bb5\u0bc8\u0baf\u0bbe\u0ba9 \u0b85\u0bb3\u0bb5\u0bc1 \u0b89\u0ba3\u0bb5\u0bc8 \u0b85\u0bb3\u0bcd\u0bb3\u0bb5\u0bc1\u0bae\u0bcd", "Child scoops food without overloading.", "\u0b9a\u0bbf\u0ba8\u0bcd\u0ba4\u0bbe\u0ba4\u0bb5\u0bbe\u0bb1\u0bc1 \u0ba4\u0bc7\u0bb5\u0bc8\u0baf\u0bbe\u0ba9 \u0b85\u0bb3\u0bb5\u0bc1 \u0b89\u0ba3\u0bb5\u0bc8 \u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bbf\u0bb2\u0bcd \u0b85\u0bb3\u0bcd\u0bb3\u0bb5\u0bc1\u0bae\u0bcd.", "Scoop up a yummy spoonful!", "\u0b92\u0bb0\u0bc1 \u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf \u0b89\u0ba3\u0bb5\u0bc8 \u0b85\u0bb3\u0bcd\u0bb3\u0bc1!"),


            StepTuple("Lift the spoon while keeping the food on it", "\u0b89\u0ba3\u0bb5\u0bc1 \u0b9a\u0bbf\u0ba8\u0bcd\u0ba4\u0bbe\u0bae\u0bb2\u0bcd \u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0b89\u0baf\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bb5\u0bc1\u0bae\u0bcd", "Child lifts spoon horizontally without tilting.", "\u0b89\u0ba3\u0bb5\u0bc1 \u0b95\u0bc0\u0bb4\u0bc7 \u0b9a\u0bbf\u0ba8\u0bcd\u0ba4\u0bbe\u0bae\u0bb2\u0bcd \u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0ba8\u0bc7\u0bb0\u0bbe\u0b95 \u0bae\u0bc7\u0bb2\u0bc7 \u0b89\u0baf\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bb5\u0bc1\u0bae\u0bcd.", "Lift the spoon carefully so it does not spill!", "\u0b9a\u0bbf\u0ba8\u0bcd\u0ba4\u0bbe\u0bae\u0bb2\u0bcd \u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0bae\u0bc7\u0bb2\u0bc7 \u0ba4\u0bc2\u0b95\u0bcd\u0b95\u0bc1!"),


            StepTuple("Move the spoon toward the mouth and open your mouth", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0bb5\u0bbe\u0baf\u0bb0\u0bc1\u0b95\u0bc7 \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0bc1 \u0bb5\u0ba8\u0bcd\u0ba4\u0bc1 \u0bb5\u0bbe\u0baf\u0bc8\u0ba4\u0bcd \u0ba4\u0bbf\u0bb1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child transports spoon level and opens mouth.", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0bb5\u0bbe\u0baf\u0bbf\u0ba9\u0bcd \u0b85\u0bb0\u0bc1\u0b95\u0bbf\u0bb2\u0bcd \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0bc1 \u0bb5\u0ba8\u0bcd\u0ba4\u0bc1 \u0bb5\u0bbe\u0baf\u0bc8\u0ba4\u0bcd \u0ba4\u0bbf\u0bb1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Bring the spoon up to your mouth and open wide!", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0bb5\u0bbe\u0baf\u0bb0\u0bc1\u0b95\u0bc7 \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0bc1 \u0bb5\u0bbe! \u0bb5\u0bbe\u0baf\u0bc8\u0ba4\u0bcd \u0ba4\u0bbf\u0bb1!"),


            StepTuple("Place the spoon into the mouth", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0bb5\u0bbe\u0baf\u0bcd\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child places spoon bowl over tongue.", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0bb5\u0bbe\u0baf\u0bcd\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0bae\u0bc6\u0ba4\u0bc1\u0bb5\u0bbe\u0b95 \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Put the spoon gently in your mouth!", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0bb5\u0bbe\u0baf\u0bbf\u0bb2\u0bcd \u0bb5\u0bc8!"),


            StepTuple("Close the lips around the spoon", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bbf\u0ba9\u0bcd \u0bae\u0bc7\u0bb2\u0bcd \u0b89\u0ba4\u0b9f\u0bc1\u0b95\u0bb3\u0bc8 \u0bae\u0bc2\u0b9f\u0bb5\u0bc1\u0bae\u0bcd", "Child seals upper lip over spoon bowl to clear food.", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bbf\u0bb2\u0bcd \u0b89\u0bb3\u0bcd\u0bb3 \u0b89\u0ba3\u0bb5\u0bc8 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95 \u0b89\u0ba4\u0b9f\u0bc1\u0b95\u0bb3\u0bc8 \u0bae\u0bc2\u0b9f\u0bb5\u0bc1\u0bae\u0bcd.", "Close your lips over the spoon to take the food!", "\u0b89\u0ba4\u0b9f\u0bc1\u0b95\u0bb3\u0bc8 \u0bae\u0bc2\u0b9f\u0bbf \u0b89\u0ba3\u0bb5\u0bc8 \u0b8e\u0b9f\u0bc1!"),


            StepTuple("Remove the spoon from the mouth", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0bb5\u0bbe\u0baf\u0bbf\u0bb2\u0bbf\u0bb0\u0bc1\u0ba8\u0bcd\u0ba4\u0bc1 \u0bb5\u0bc6\u0bb3\u0bbf\u0baf\u0bc7 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child withdraws spoon horizontally.", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0bb5\u0bbe\u0baf\u0bbf\u0bb2\u0bbf\u0bb0\u0bc1\u0ba8\u0bcd\u0ba4\u0bc1 \u0bb5\u0bc6\u0bb3\u0bbf\u0baf\u0bc7 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Take the spoon out of your mouth!", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0bb5\u0bc6\u0bb3\u0bbf\u0baf\u0bc7 \u0b8e\u0b9f\u0bc1!"),


            StepTuple("Keep the food in the mouth", "\u0b89\u0ba3\u0bb5\u0bc8 \u0bb5\u0bbe\u0baf\u0bcd\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0bb5\u0bc8\u0ba4\u0bcd\u0ba4\u0bbf\u0bb0\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child retains food bolus in oral cavity.", "\u0b89\u0ba3\u0bb5\u0bc8 \u0b9a\u0bbf\u0ba8\u0bcd\u0ba4\u0bbe\u0bae\u0bb2\u0bcd \u0bb5\u0bbe\u0baf\u0bcd\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0bb5\u0bc8\u0ba4\u0bcd\u0ba4\u0bbf\u0bb0\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Keep the yummy food inside your mouth!", "\u0b89\u0ba3\u0bb5\u0bc8 \u0bb5\u0bbe\u0baf\u0bcd\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0bb5\u0bc8!"),


            StepTuple("Chew the food as needed", "\u0b89\u0ba3\u0bb5\u0bc8 \u0ba8\u0ba9\u0bcd\u0bb1\u0bbe\u0b95 \u0bae\u0bc6\u0bb2\u0bcd\u0bb2\u0bb5\u0bc1\u0bae\u0bcd", "Child masticates food thoroughly.", "\u0b89\u0ba3\u0bb5\u0bc8 \u0baa\u0bb1\u0bcd\u0b95\u0bb3\u0bbe\u0bb2\u0bcd \u0ba8\u0ba9\u0bcd\u0bb1\u0bbe\u0b95 \u0bae\u0bc6\u0bb2\u0bcd\u0bb2\u0bb5\u0bc1\u0bae\u0bcd.", "Chew your food nicely!", "\u0ba8\u0ba9\u0bcd\u0bb1\u0bbe\u0b95 \u0bae\u0bc6\u0bb2\u0bcd\u0bb2\u0bc1!"),


            StepTuple("Swallow the food", "\u0b89\u0ba3\u0bb5\u0bc8 \u0bb5\u0bbf\u0bb4\u0bc1\u0b99\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child swallows food completely.", "\u0b89\u0ba3\u0bb5\u0bc8 \u0bae\u0bc1\u0bb4\u0bc1\u0bae\u0bc8\u0baf\u0bbe\u0b95 \u0bb5\u0bbf\u0bb4\u0bc1\u0b99\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Swallow the food down!", "\u0b89\u0ba3\u0bb5\u0bc8 \u0bb5\u0bbf\u0bb4\u0bc1\u0b99\u0bcd\u0b95\u0bc1!"),


            StepTuple("Lower the spoon toward the bowl/plate", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0bae\u0bc0\u0ba3\u0bcd\u0b9f\u0bc1\u0bae\u0bcd \u0b95\u0bbf\u0ba3\u0bcd\u0ba3\u0ba4\u0bcd\u0ba4\u0bc8 \u0ba8\u0bcb\u0b95\u0bcd\u0b95\u0bbf \u0b87\u0bb1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child lowers empty spoon to food dish.", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0bae\u0bc0\u0ba3\u0bcd\u0b9f\u0bc1\u0bae\u0bcd \u0b95\u0bbf\u0ba3\u0bcd\u0ba3\u0ba4\u0bcd\u0ba4\u0bc8 \u0ba8\u0bcb\u0b95\u0bcd\u0b95\u0bbf \u0b95\u0bc0\u0bb4\u0bc7 \u0b87\u0bb1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Lower your spoon back to the bowl!", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0bae\u0bc0\u0ba3\u0bcd\u0b9f\u0bc1\u0bae\u0bcd \u0b95\u0bbf\u0ba3\u0bcd\u0ba3\u0ba4\u0bcd\u0ba4\u0bc1\u0b95\u0bcd\u0b95\u0bc1\u0b95\u0bcd \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0bc1 \u0bb5\u0bbe!"),


            StepTuple("Scoop the next appropriate amount of food", "\u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0bb5\u0bbe\u0baf\u0bcd \u0b89\u0ba3\u0bb5\u0bc8 \u0b85\u0bb3\u0bcd\u0bb3\u0bb5\u0bc1\u0bae\u0bcd", "Child scoops second bite.", "\u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0bb5\u0bbe\u0baf\u0bcd \u0b89\u0ba3\u0bb5\u0bc8 \u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bbf\u0bb2\u0bcd \u0b85\u0bb3\u0bcd\u0bb3\u0bb5\u0bc1\u0bae\u0bcd.", "Scoop up another delicious bite!", "\u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0bb5\u0bbe\u0baf\u0bcd \u0b89\u0ba3\u0bb5\u0bc8 \u0b85\u0bb3\u0bcd\u0bb3\u0bc1!"),


            StepTuple("Repeat the sequence until the desired portion is eaten", "\u0b9a\u0bbe\u0baa\u0bcd\u0baa\u0bbf\u0b9f\u0bcd\u0b9f\u0bc1 \u0bae\u0bc1\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bc1\u0bae\u0bcd \u0bb5\u0bb0\u0bc8 \u0ba4\u0bca\u0b9f\u0bb0\u0bb5\u0bc1\u0bae\u0bcd", "Child continues spoon feeding independently.", "\u0bb5\u0baf\u0bbf\u0bb1\u0bc1 \u0ba8\u0bbf\u0bb1\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0bb5\u0bb0\u0bc8 \u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bbe\u0bb2\u0bcd \u0b9a\u0bbe\u0baa\u0bcd\u0baa\u0bbf\u0b9f\u0bcd\u0b9f\u0bc1 \u0bae\u0bc1\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Keep eating until your bowl is clean!", "\u0bae\u0bc1\u0bb4\u0bc1\u0bae\u0bc8\u0baf\u0bbe\u0b95 \u0b9a\u0bbe\u0baa\u0bcd\u0baa\u0bbf\u0b9f\u0bcd\u0b9f\u0bc1 \u0bae\u0bc1\u0b9f\u0bbf!"),


            StepTuple("Place the spoon down when finished", "\u0b9a\u0bbe\u0baa\u0bcd\u0baa\u0bbf\u0b9f\u0bcd\u0b9f\u0bc1 \u0bae\u0bc1\u0b9f\u0bbf\u0ba4\u0bcd\u0ba4\u0ba4\u0bc1\u0bae\u0bcd \u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0b95\u0bc0\u0bb4\u0bc7 \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child rests spoon on plate or table.", "\u0b9a\u0bbe\u0baa\u0bcd\u0baa\u0bbf\u0b9f\u0bcd\u0b9f\u0bc1 \u0bae\u0bc1\u0b9f\u0bbf\u0ba4\u0bcd\u0ba4\u0ba4\u0bc1\u0bae\u0bcd \u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0ba4\u0b9f\u0bcd\u0b9f\u0bbf\u0bb2\u0bcd \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Put your spoon down on the table!", "\u0b95\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bc8 \u0b95\u0bc0\u0bb4\u0bc7 \u0bb5\u0bc8!"),


            StepTuple("Check that the eating area is reasonably clean", "\u0b9a\u0bbe\u0baa\u0bcd\u0baa\u0bbf\u0b9f\u0bcd\u0b9f \u0b87\u0b9f\u0ba4\u0bcd\u0ba4\u0bc8 \u0b9a\u0bb0\u0bbf\u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child checks table for dropped food.", "\u0b9a\u0bbe\u0baa\u0bcd\u0baa\u0bbf\u0b9f\u0bcd\u0b9f \u0bae\u0bc7\u0b9c\u0bc8 \u0b9a\u0bc1\u0ba4\u0bcd\u0ba4\u0bae\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Look at the table! Nice and clean!", "\u0bae\u0bc7\u0b9c\u0bc8 \u0b9a\u0bc1\u0ba4\u0bcd\u0ba4\u0bae\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd!"),


            StepTuple("Wipe the mouth/hands if needed", "\u0bb5\u0bbe\u0baf\u0bcd \u0bae\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0b95\u0bc8\u0b95\u0bb3\u0bc8\u0ba4\u0bcd \u0ba4\u0bc1\u0b9f\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child uses napkin to clean mouth and hands.", "\u0bb5\u0bbe\u0baf\u0bcd \u0bae\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0b95\u0bc8\u0b95\u0bb3\u0bc8 \u0ba8\u0bbe\u0baa\u0bcd\u0b95\u0bbf\u0ba9\u0bbe\u0bb2\u0bcd \u0b9a\u0bc1\u0ba4\u0bcd\u0ba4\u0bae\u0bbe\u0b95\u0ba4\u0bcd \u0ba4\u0bc1\u0b9f\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Wipe your mouth and smile! Super job with the spoon!", "\u0bb5\u0bbe\u0baf\u0bc8\u0ba4\u0bcd \u0ba4\u0bc1\u0b9f\u0bc8\u0ba4\u0bcd\u0ba4\u0bc1 \u0b9a\u0bbf\u0bb0\u0bbf! \u0b85\u0bb0\u0bc1\u0bae\u0bc8\u0baf\u0bbe\u0b95 \u0b9a\u0bbe\u0baa\u0bcd\u0baa\u0bbf\u0b9f\u0bcd\u0b9f\u0bbe\u0baf\u0bcd!"),


        ),


        16L to listOf(


            StepTuple("Move to a private changing area", "\u0ba4\u0ba9\u0bbf\u0baa\u0bcd\u0baa\u0b9f\u0bcd\u0b9f \u0b85\u0bb1\u0bc8\u0b95\u0bcd\u0b95\u0bc1\u0b9a\u0bcd \u0b9a\u0bc6\u0bb2\u0bcd\u0bb2\u0bb5\u0bc1\u0bae\u0bcd", "Guide child to private area for dressing.", "\u0b95\u0bc1\u0bb4\u0ba8\u0bcd\u0ba4\u0bc8\u0baf\u0bc8 \u0ba4\u0ba9\u0bbf\u0baa\u0bcd\u0baa\u0b9f\u0bcd\u0b9f \u0b89\u0b9f\u0bc8 \u0bae\u0bbe\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0b87\u0b9f\u0ba4\u0bcd\u0ba4\u0bbf\u0bb1\u0bcd\u0b95\u0bc1 \u0b85\u0bb4\u0bc8\u0ba4\u0bcd\u0ba4\u0bc1\u0b9a\u0bcd \u0b9a\u0bc6\u0bb2\u0bcd\u0bb2\u0bb5\u0bc1\u0bae\u0bcd.", "Let us step into your changing area!", "\u0b89\u0b9f\u0bc8 \u0bae\u0bbe\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0b85\u0bb1\u0bc8\u0b95\u0bcd\u0b95\u0bc1 \u0bb5\u0bbe!"),


            StepTuple("Pick up the underwear", "\u0b89\u0bb3\u0bcd\u0bb3\u0bbe\u0b9f\u0bc8\u0baf\u0bc8 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child picks up clean briefs.", "\u0b9a\u0bc1\u0ba4\u0bcd\u0ba4\u0bae\u0bbe\u0ba9 \u0b89\u0bb3\u0bcd\u0bb3\u0bbe\u0b9f\u0bc8\u0baf\u0bc8 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Pick up your clean underwear!", "\u0b89\u0bb3\u0bcd\u0bb3\u0bbe\u0b9f\u0bc8\u0baf\u0bc8 \u0b8e\u0b9f\u0bc1!"),


            StepTuple("Identify the front and back", "\u0bae\u0bc1\u0ba9\u0bcd\u0baa\u0bc1\u0bb1\u0bae\u0bcd \u0bae\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0baa\u0bbf\u0ba9\u0bcd\u0baa\u0bc1\u0bb1\u0ba4\u0bcd\u0ba4\u0bc8 \u0b85\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child finds waistband tag on back.", "\u0baa\u0bbf\u0ba9\u0bcd\u0baa\u0b95\u0bcd\u0b95 \u0bb2\u0bc7\u0baa\u0bbf\u0bb3\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Find the tag on the back!", "\u0baa\u0bbf\u0ba9\u0bcd\u0baa\u0b95\u0bcd\u0b95 \u0bb2\u0bc7\u0baa\u0bbf\u0bb3\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bc1\u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Identify the waistband", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child locates elastic top.", "\u0b8e\u0bb2\u0bbe\u0bb8\u0bcd\u0b9f\u0bbf\u0b95\u0bcd \u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8\u0ba4\u0bcd \u0ba4\u0bca\u0b9f\u0bb5\u0bc1\u0bae\u0bcd.", "Find the waistband!", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8\u0ba4\u0bcd \u0ba4\u0bca\u0b9f\u0bc1!"),


            StepTuple("Identify the right and left leg openings", "\u0b87\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0bcd \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0b99\u0bcd\u0b95\u0bb3\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b85\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child locates both leg openings.", "\u0b87\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0bcd \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0b99\u0bcd\u0b95\u0bb3\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b85\u0b9f\u0bc8\u0baf\u0bbe\u0bb3\u0bae\u0bcd \u0b95\u0bbe\u0ba3\u0bb5\u0bc1\u0bae\u0bcd.", "Find both leg holes!", "\u0b87\u0bb0\u0bc1 \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0b99\u0bcd\u0b95\u0bb3\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0baa\u0bbe\u0bb0\u0bcd!"),


            StepTuple("Hold the waistband with both hands", "\u0b87\u0bb0\u0bc1 \u0b95\u0bc8\u0b95\u0bb3\u0bbe\u0bb2\u0bc1\u0bae\u0bcd \u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child grasps sides of waistband.", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0b87\u0bb0\u0bc1 \u0b95\u0bc8\u0b95\u0bb3\u0bbe\u0bb2\u0bc1\u0bae\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Hold the waistband with both hands!", "\u0b87\u0bb0\u0bc1 \u0b95\u0bc8\u0b95\u0bb3\u0bbe\u0bb2\u0bc1\u0bae\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Open the waistband", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0bb5\u0bbf\u0bb0\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child stretches opening wide.", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0bb5\u0bbf\u0bb0\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Stretch the waistband open wide!", "\u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0b85\u0b95\u0bb2\u0bae\u0bbe\u0b95 \u0bb5\u0bbf\u0bb0\u0bbf!"),


            StepTuple("Step one foot into the corresponding leg opening", "\u0b92\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0bc8 \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0ba4\u0bcd\u0ba4\u0bbf\u0bb2\u0bcd \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child steps foot in.", "\u0b92\u0bb0\u0bc1 \u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0b89\u0bb3\u0bcd\u0bb3\u0bc7 \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Step one foot into the leg hole!", "\u0b92\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0bc8 \u0b89\u0bb3\u0bcd\u0bb3\u0bc7 \u0bb5\u0bc8!"),


            StepTuple("Push the foot through the opening", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0bae\u0bcd \u0bb5\u0bb4\u0bbf\u0baf\u0bc7 \u0bb5\u0bc6\u0bb3\u0bbf\u0baf\u0bc7 \u0ba4\u0bb3\u0bcd\u0bb3\u0bb5\u0bc1\u0bae\u0bcd", "Child extends foot completely through.", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0bb5\u0bc6\u0bb3\u0bbf\u0baf\u0bc7 \u0ba4\u0bb3\u0bcd\u0bb3\u0bb5\u0bc1\u0bae\u0bcd.", "Push your foot all the way through!", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0bb5\u0bc6\u0bb3\u0bbf\u0baf\u0bc7 \u0ba4\u0bb3\u0bcd\u0bb3\u0bc1!"),


            StepTuple("Step the other foot into the other leg opening", "\u0bae\u0bb1\u0bcd\u0bb1\u0bca\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0bc8 \u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0ba4\u0bcd\u0ba4\u0bbf\u0bb2\u0bcd \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child steps second foot in.", "\u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0bae\u0bb1\u0bcd\u0bb1 \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0ba4\u0bcd\u0ba4\u0bbf\u0bb2\u0bcd \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Step your other foot in!", "\u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0b95\u0bbe\u0bb2\u0bc8 \u0b89\u0bb3\u0bcd\u0bb3\u0bc7 \u0bb5\u0bc8!"),


