            StepTuple("Pull the underwear upward toward the thighs", "\u0ba4\u0bca\u0b9f\u0bc8 \u0bb5\u0bb0\u0bc8 \u0bae\u0bc7\u0bb2\u0bc7 \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child pulls panties onto thighs.", "\u0b89\u0bb3\u0bcd\u0bb3\u0bbe\u0b9f\u0bc8\u0baf\u0bc8 \u0ba4\u0bca\u0b9f\u0bc8 \u0bb5\u0bb0\u0bc8 \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Pull up to your thighs!", "\u0ba4\u0bca\u0b9f\u0bc8 \u0bb5\u0bb0\u0bc8 \u0b87\u0bb4\u0bc1!"),


            StepTuple("Pull the waistband upward toward the waist", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1 \u0bb5\u0bb0\u0bc8 \u0bae\u0bc7\u0bb2\u0bc7 \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child pulls waistband to waist.", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8 \u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1 \u0bb5\u0bb0\u0bc8 \u0bae\u0bc7\u0bb2\u0bc7 \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Pull the waistband up to your waist!", "\u0b87\u0b9f\u0bc1\u0baa\u0bcd\u0baa\u0bc1 \u0bb5\u0bb0\u0bc8 \u0bae\u0bc7\u0bb2\u0bc7 \u0b87\u0bb4\u0bc1!"),


            StepTuple("Adjust the front and back", "\u0bae\u0bc1\u0ba9\u0bcd\u0baa\u0bc1\u0bb1\u0bae\u0bcd \u0bae\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0baa\u0bbf\u0ba9\u0bcd\u0baa\u0bc1\u0bb1\u0ba4\u0bcd\u0ba4\u0bc8 \u0b9a\u0bb0\u0bbf\u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child balances coverage.", "\u0bae\u0bc1\u0ba9\u0bcd\u0baa\u0bc1\u0bb1\u0bae\u0bc1\u0bae\u0bcd \u0baa\u0bbf\u0ba9\u0bcd\u0baa\u0bc1\u0bb1\u0bae\u0bc1\u0bae\u0bcd \u0b9a\u0bc0\u0bb0\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9 \u0b9a\u0bb0\u0bbf\u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Adjust the front and back evenly!", "\u0bae\u0bc1\u0ba9\u0bcd\u0baa\u0b95\u0bcd\u0b95\u0bae\u0bc1\u0bae\u0bcd \u0baa\u0bbf\u0ba9\u0bcd\u0baa\u0b95\u0bcd\u0b95\u0bae\u0bc1\u0bae\u0bcd \u0b9a\u0bb0\u0bbf\u0b9a\u0bc6\u0baf\u0bcd!"),


            StepTuple("Check that both legs are correctly positioned", "\u0b87\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0bcd\u0b95\u0bb3\u0bc1\u0bae\u0bcd \u0b9a\u0bb0\u0bbf\u0baf\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child checks leg openings fit comfortably.", "\u0b95\u0bbe\u0bb2\u0bcd \u0ba4\u0bc1\u0bb5\u0bbe\u0bb0\u0b99\u0bcd\u0b95\u0bb3\u0bcd \u0bb5\u0b9a\u0ba4\u0bbf\u0baf\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Make sure both legs feel comfy!", "\u0b87\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0bcd\u0b95\u0bb3\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0baa\u0bbe\u0bb0\u0bcd!"),


