            StepTuple("Pick up the correct shoe", "\u0b9a\u0bb0\u0bbf\u0baf\u0bbe\u0ba9 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8 \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child lifts shoe for chosen foot.", "\u0b85\u0ba3\u0bbf\u0baf \u0bb5\u0bc7\u0ba3\u0bcd\u0b9f\u0bbf\u0baf \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8\u0b95\u0bcd \u0b95\u0bc8\u0baf\u0bbf\u0bb2\u0bcd \u0b8e\u0b9f\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Pick up the shoe for your foot!", "\u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8 \u0b8e\u0b9f\u0bc1!"),


            StepTuple("Identify the front of the shoe", "\u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bbf\u0ba9\u0bcd \u0bae\u0bc1\u0ba9\u0bcd\u0baa\u0bc1\u0bb1\u0ba4\u0bcd\u0ba4\u0bc8 \u0b85\u0b9f\u0bc8\u0baf\u0bbe\u0bb3\u0bae\u0bcd \u0b95\u0bbe\u0ba3\u0bb5\u0bc1\u0bae\u0bcd", "Child locates front toe area.", "\u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bbf\u0ba9\u0bcd \u0bae\u0bc1\u0ba9\u0bcd \u0bb5\u0bbf\u0bb0\u0bb2\u0bcd \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0baf\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Find the front where your toes go!", "\u0bae\u0bc1\u0ba9\u0bcd\u0baa\u0b95\u0bcd\u0b95\u0ba4\u0bcd\u0ba4\u0bc8\u0b95\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bc1\u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Hold the shoe open", "\u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8 \u0b87\u0bb0\u0bc1 \u0b95\u0bc8\u0b95\u0bb3\u0bbe\u0bb2\u0bc1\u0bae\u0bcd \u0ba4\u0bbf\u0bb1\u0ba8\u0bcd\u0ba4\u0bc1 \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child holds sides of opening.", "\u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bbf\u0ba9\u0bcd \u0ba4\u0bbf\u0bb1\u0baa\u0bcd\u0baa\u0bc1\u0baa\u0bcd \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0baf\u0bc8 \u0b87\u0bb0\u0bc1 \u0b95\u0bc8\u0b95\u0bb3\u0bbe\u0bb2\u0bc1\u0bae\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Hold the shoe collar open!", "\u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8\u0ba4\u0bcd \u0ba4\u0bbf\u0bb1\u0ba8\u0bcd\u0ba4\u0bc1 \u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Lift the corresponding foot", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0b89\u0baf\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bb5\u0bc1\u0bae\u0bcd", "Child brings foot to shoe entrance.", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bbf\u0ba9\u0bcd \u0bae\u0bc1\u0ba9\u0bcd \u0b89\u0baf\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bb5\u0bc1\u0bae\u0bcd.", "Lift your foot up to the shoe!", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0bae\u0bc7\u0bb2\u0bc7 \u0ba4\u0bc2\u0b95\u0bcd\u0b95\u0bc1!"),


            StepTuple("Place the toes into the shoe", "\u0b95\u0bbe\u0bb2\u0bcd \u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bc8 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child guides toes in.", "\u0b95\u0bbe\u0bb2\u0bcd \u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bc8 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Put your toes inside the shoe!", "\u0bb5\u0bbf\u0bb0\u0bb2\u0bcd\u0b95\u0bb3\u0bc8 \u0b89\u0bb3\u0bcd\u0bb3\u0bc7 \u0bb5\u0bc8!"),


            StepTuple("Slide the foot forward", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0bae\u0bc1\u0ba9\u0bcd\u0ba9\u0bcb\u0b95\u0bcd\u0b95\u0bbf \u0ba4\u0bb3\u0bcd\u0bb3\u0bb5\u0bc1\u0bae\u0bcd", "Child glides foot into front of shoe.", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0bae\u0bc1\u0ba9\u0bcd\u0ba9\u0bcb\u0b95\u0bcd\u0b95\u0bbf \u0ba8\u0b95\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bb5\u0bc1\u0bae\u0bcd.", "Slide your foot forward!", "\u0baa\u0bbe\u0ba4\u0ba4\u0bcd\u0ba4\u0bc8 \u0bae\u0bc1\u0ba9\u0bcd\u0ba9\u0bbe\u0bb2\u0bcd \u0ba4\u0bb3\u0bcd\u0bb3\u0bc1!"),


            StepTuple("Push the heel down into the shoe", "\u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bc8 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0b95\u0bc0\u0bb4\u0bc7 \u0b85\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bb5\u0bc1\u0bae\u0bcd", "Child presses heel firmly into shoe.", "\u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bc8 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bbf\u0ba9\u0bcd \u0ba4\u0bb0\u0bc8\u0baa\u0bcd\u0baa\u0b95\u0bc1\u0ba4\u0bbf \u0bb5\u0bb0\u0bc8 \u0b95\u0bc0\u0bb4\u0bc7 \u0b85\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bb5\u0bc1\u0bae\u0bcd.", "Push your heel down in!", "\u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bbe\u0bb2\u0bc8 \u0b95\u0bc0\u0bb4\u0bc7 \u0b85\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bc1!"),


            StepTuple("Check that the entire foot is inside", "\u0bae\u0bc1\u0bb4\u0bc1\u0baa\u0bcd \u0baa\u0bbe\u0ba4\u0bae\u0bc1\u0bae\u0bcd \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bcd\u0b95\u0bc1\u0bb3\u0bcd \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child confirms heel and foot are fully seated.", "\u0bae\u0bc1\u0bb4\u0bc1\u0baa\u0bcd \u0baa\u0bbe\u0ba4\u0bae\u0bc1\u0bae\u0bcd \u0b89\u0bb3\u0bcd\u0bb3\u0bc7 \u0b9a\u0bc6\u0ba9\u0bcd\u0bb1\u0bc1\u0bb3\u0bcd\u0bb3\u0ba4\u0bc8 \u0b89\u0bb1\u0bc1\u0ba4\u0bbf\u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Make sure your whole foot is inside!", "\u0baa\u0bbe\u0ba4\u0bae\u0bcd \u0bae\u0bc1\u0bb4\u0bc1\u0bae\u0bc8\u0baf\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0bc7 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd!"),


            StepTuple("Adjust the shoe if necessary", "\u0ba4\u0bc7\u0bb5\u0bc8\u0baa\u0bcd\u0baa\u0b9f\u0bcd\u0b9f\u0bbe\u0bb2\u0bcd \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8 \u0b9a\u0bb0\u0bbf\u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child pulls back tab or adjusts fit.", "\u0ba4\u0bc7\u0bb5\u0bc8\u0baa\u0bcd\u0baa\u0b9f\u0bcd\u0b9f\u0bbe\u0bb2\u0bcd \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bbf\u0ba9\u0bcd \u0baa\u0bbf\u0ba9\u0bcd \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0baf\u0bc8 \u0b9a\u0bb0\u0bbf\u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Fix the back if you need to!", "\u0baa\u0bbf\u0ba9\u0bcd\u0baa\u0b95\u0bcd\u0b95\u0ba4\u0bcd\u0ba4\u0bc8 \u0b9a\u0bb0\u0bbf\u0b9a\u0bc6\u0baf\u0bcd!"),


            StepTuple("Repeat with the other shoe", "\u0bae\u0bb1\u0bcd\u0bb1\u0bca\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b85\u0bb5\u0bcd\u0bb5\u0bbe\u0bb1\u0bc7 \u0b85\u0ba3\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child puts second slip-on shoe on.", "\u0bae\u0bb1\u0bcd\u0bb1\u0bca\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0b95\u0bbe\u0bb2\u0bbf\u0bb2\u0bcd \u0b85\u0ba3\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Now put on the other shoe!", "\u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0baf\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0baa\u0bcb\u0b9f\u0bc1!"),


            StepTuple("Check that both shoes are correctly positioned, stand safely, and are comfortable", "\u0b87\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bb3\u0bc1\u0bae\u0bcd \u0bb5\u0b9a\u0ba4\u0bbf\u0baf\u0bbe\u0b95\u0bb5\u0bc1\u0bae\u0bcd \u0b9a\u0bb0\u0bbf\u0baf\u0bbe\u0b95\u0bb5\u0bc1\u0bae\u0bcd \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child stands and confirms comfort.", "\u0b8e\u0bb4\u0bc1\u0ba8\u0bcd\u0ba4\u0bc1 \u0ba8\u0bbf\u0ba9\u0bcd\u0bb1\u0bc1 \u0b87\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bb3\u0bc1\u0bae\u0bcd \u0bb5\u0b9a\u0ba4\u0bbf\u0baf\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bc8 \u0b89\u0bb1\u0bc1\u0ba4\u0bbf\u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "All slipped on! Walk around, you are ready!", "\u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bb3\u0bcd \u0baa\u0bcb\u0b9f\u0bcd\u0b9f\u0bbe\u0b9a\u0bcd\u0b9a\u0bc1! \u0b85\u0bb0\u0bc1\u0bae\u0bc8!"),


        ),


        27L to listOf(


            StepTuple("Find both laces", "\u0b87\u0bb0\u0bc1 \u0b95\u0baf\u0bbf\u0bb1\u0bc1\u0b95\u0bb3\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bb1\u0bbf\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child locates left and right shoe laces.", "\u0b87\u0b9f\u0ba4\u0bc1 \u0bae\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0bb5\u0bb2\u0ba4\u0bc1 \u0b95\u0baf\u0bbf\u0bb1\u0bc1\u0b95\u0bb3\u0bc8 \u0b85\u0b9f\u0bc8\u0baf\u0bbe\u0bb3\u0bae\u0bcd \u0b95\u0bbe\u0ba3\u0bb5\u0bc1\u0bae\u0bcd.", "Find both of your shoelaces!", "\u0b87\u0bb0\u0bc1 \u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bcd \u0b95\u0baf\u0bbf\u0bb1\u0bc1\u0b95\u0bb3\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b95\u0ba3\u0bcd\u0b9f\u0bc1\u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Hold one lace in each hand", "\u0b92\u0bb5\u0bcd\u0bb5\u0bca\u0bb0\u0bc1 \u0b95\u0bc8\u0baf\u0bbf\u0bb2\u0bc1\u0bae\u0bcd \u0b92\u0bb0\u0bc1 \u0b95\u0baf\u0bbf\u0bb1\u0bcd\u0bb1\u0bc8\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child grips left lace in left hand, right lace in right hand.", "\u0b92\u0bb5\u0bcd\u0bb5\u0bca\u0bb0\u0bc1 \u0b95\u0bc8\u0baf\u0bbf\u0bb2\u0bc1\u0bae\u0bcd \u0b92\u0bb0\u0bc1 \u0b95\u0baf\u0bbf\u0bb1\u0bcd\u0bb1\u0bc8\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Hold one lace in each hand!", "\u0b87\u0bb0\u0bc1 \u0b95\u0bc8\u0b95\u0bb3\u0bbf\u0bb2\u0bc1\u0bae\u0bcd \u0b95\u0baf\u0bbf\u0bb1\u0bc1\u0b95\u0bb3\u0bc8\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf!"),


            StepTuple("Cross the laces", "\u0b95\u0baf\u0bbf\u0bb1\u0bc1\u0b95\u0bb3\u0bc8 \u0b95\u0bc1\u0bb1\u0bc1\u0b95\u0bcd\u0b95\u0bbe\u0b95 \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child crosses laces to make an X.", "\u0b95\u0baf\u0bbf\u0bb1\u0bc1\u0b95\u0bb3\u0bc8 \u0b92\u0ba9\u0bcd\u0bb1\u0ba9\u0bcd \u0bae\u0bc7\u0bb2\u0bcd \u0b92\u0ba9\u0bcd\u0bb1\u0bbe\u0b95 \u0b95\u0bc1\u0bb1\u0bc1\u0b95\u0bcd\u0b95\u0bbe\u0b95 \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Cross the laces to make a big X!", "\u0b95\u0baf\u0bbf\u0bb1\u0bc1\u0b95\u0bb3\u0bc8 \u0b95\u0bc1\u0bb1\u0bc1\u0b95\u0bcd\u0b95\u0bbe\u0b95 \u0bb5\u0bc8! X \u0baa\u0bcb\u0bb2!"),


            StepTuple("Make the first knot", "\u0bae\u0bc1\u0ba4\u0bb2\u0bcd \u0bae\u0bc1\u0b9f\u0bbf\u0b9a\u0bcd\u0b9a\u0bc8 \u0b89\u0bb0\u0bc1\u0bb5\u0bbe\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child tucks one lace under and pulls tight.", "\u0b92\u0bb0\u0bc1 \u0b95\u0baf\u0bbf\u0bb1\u0bcd\u0bb1\u0bc8 \u0b95\u0bc0\u0bb4\u0bc7 \u0ba8\u0bc1\u0bb4\u0bc8\u0ba4\u0bcd\u0ba4\u0bc1 \u0b87\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bc1 \u0bae\u0bc1\u0ba4\u0bb2\u0bcd \u0bae\u0bc1\u0b9f\u0bbf\u0b9a\u0bcd\u0b9a\u0bc1 \u0baa\u0bcb\u0b9f\u0bb5\u0bc1\u0bae\u0bcd.", "Tuck one under and pull tight for the first knot!", "\u0b95\u0bc0\u0bb4\u0bc7 \u0ba8\u0bc1\u0bb4\u0bc8\u0ba4\u0bcd\u0ba4\u0bc1 \u0b87\u0bb4\u0bc1! \u0bae\u0bc1\u0ba4\u0bb2\u0bcd \u0bae\u0bc1\u0b9f\u0bbf\u0b9a\u0bcd\u0b9a\u0bc1!"),


            StepTuple("Make one loop", "\u0b92\u0bb0\u0bc1 \u0b9a\u0bc1\u0bb0\u0bc1\u0b95\u0bcd\u0b95\u0bc1 \u0bb5\u0bb3\u0bc8\u0baf\u0bae\u0bcd \u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd", "Child folds one lace into a loop (bunny ear).", "\u0b92\u0bb0\u0bc1 \u0b95\u0baf\u0bbf\u0bb1\u0bcd\u0bb1\u0bbf\u0bb2\u0bcd \u0bae\u0bc1\u0baf\u0bb2\u0bcd \u0b95\u0bbe\u0ba4\u0bc1 \u0baa\u0bcb\u0bb2 \u0b9a\u0bbf\u0bb1\u0bbf\u0baf \u0bb5\u0bb3\u0bc8\u0baf\u0bae\u0bcd \u0b9a\u0bc6\u0baf\u0bcd\u0baf\u0bb5\u0bc1\u0bae\u0bcd.", "Make a loop like a bunny ear!", "\u0b92\u0bb0\u0bc1 \u0bae\u0bc1\u0baf\u0bb2\u0bcd \u0b95\u0bbe\u0ba4\u0bc1 \u0bb5\u0bb3\u0bc8\u0baf\u0bae\u0bcd \u0b9a\u0bc6\u0baf\u0bcd!"),


            StepTuple("Wrap the other lace around the loop", "\u0bae\u0bb1\u0bcd\u0bb1\u0bca\u0bb0\u0bc1 \u0b95\u0baf\u0bbf\u0bb1\u0bcd\u0bb1\u0bc8 \u0bb5\u0bb3\u0bc8\u0baf\u0ba4\u0bcd\u0ba4\u0bc8\u0b9a\u0bcd \u0b9a\u0bc1\u0bb1\u0bcd\u0bb1\u0bbf \u0b9a\u0bc1\u0bb1\u0bcd\u0bb1\u0bb5\u0bc1\u0bae\u0bcd", "Child winds second lace around base of loop.", "\u0bae\u0bb1\u0bcd\u0bb1\u0bca\u0bb0\u0bc1 \u0b95\u0baf\u0bbf\u0bb1\u0bcd\u0bb1\u0bc8 \u0b85\u0ba8\u0bcd\u0ba4 \u0bb5\u0bb3\u0bc8\u0baf\u0ba4\u0bcd\u0ba4\u0bc8\u0b9a\u0bcd \u0b9a\u0bc1\u0bb1\u0bcd\u0bb1\u0bbf \u0b9a\u0bc1\u0bb1\u0bcd\u0bb1\u0bb5\u0bc1\u0bae\u0bcd.", "Wrap the other lace all the way around the loop!", "\u0b9a\u0bc1\u0bb1\u0bcd\u0bb1\u0bbf \u0bb5\u0bb3\u0bc8\u0ba4\u0bcd\u0ba4\u0bc1 \u0b8e\u0b9f\u0bc1!"),


            StepTuple("Push the lace through", "\u0b95\u0baf\u0bbf\u0bb1\u0bcd\u0bb1\u0bc8 \u0ba4\u0bc1\u0bb3\u0bc8 \u0bb5\u0bb4\u0bbf\u0baf\u0bc7 \u0ba4\u0bb3\u0bcd\u0bb3\u0bb5\u0bc1\u0bae\u0bcd", "Child pushes middle of wrapped lace through opening.", "\u0b95\u0baf\u0bbf\u0bb1\u0bcd\u0bb1\u0bc8 \u0ba4\u0bc1\u0bb3\u0bc8 \u0bb5\u0bb4\u0bbf\u0baf\u0bc7 \u0ba4\u0bb3\u0bcd\u0bb3\u0bbf \u0bb5\u0bc6\u0bb3\u0bbf\u0baf\u0bc7 \u0b95\u0bca\u0ba3\u0bcd\u0b9f\u0bc1 \u0bb5\u0bb0\u0bb5\u0bc1\u0bae\u0bcd.", "Push the lace through the little hole!", "\u0ba4\u0bc1\u0bb3\u0bc8 \u0bb5\u0bb4\u0bbf\u0baf\u0bc7 \u0b89\u0bb3\u0bcd\u0bb3\u0bc7 \u0ba4\u0bb3\u0bcd\u0bb3\u0bc1!"),


            StepTuple("Make the second loop", "\u0b87\u0bb0\u0ba3\u0bcd\u0b9f\u0bbe\u0bb5\u0ba4\u0bc1 \u0bb5\u0bb3\u0bc8\u0baf\u0ba4\u0bcd\u0ba4\u0bc8 \u0b89\u0bb0\u0bc1\u0bb5\u0bbe\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child grasps the emerging second loop.", "\u0b87\u0bb0\u0ba3\u0bcd\u0b9f\u0bbe\u0bb5\u0ba4\u0bc1 \u0bb5\u0bb3\u0bc8\u0baf\u0ba4\u0bcd\u0ba4\u0bc8\u0baa\u0bcd \u0baa\u0bbf\u0b9f\u0bbf\u0ba4\u0bcd\u0ba4\u0bc1 \u0bb5\u0bc6\u0bb3\u0bbf\u0baf\u0bc7 \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Pull the second bunny ear out!", "\u0b87\u0bb0\u0ba3\u0bcd\u0b9f\u0bbe\u0bb5\u0ba4\u0bc1 \u0bae\u0bc1\u0baf\u0bb2\u0bcd \u0b95\u0bbe\u0ba4\u0bc8 \u0bb5\u0bc6\u0bb3\u0bbf\u0baf\u0bc7 \u0b87\u0bb4\u0bc1!"),


            StepTuple("Pull both loops tight", "\u0b87\u0bb0\u0bc1 \u0bb5\u0bb3\u0bc8\u0baf\u0b99\u0bcd\u0b95\u0bb3\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b87\u0bb1\u0bc1\u0b95\u0bcd\u0b95\u0bae\u0bbe\u0b95 \u0b87\u0bb4\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child pulls both loops outward until snug.", "\u0b87\u0bb0\u0bc1 \u0bb5\u0bb3\u0bc8\u0baf\u0b99\u0bcd\u0b95\u0bb3\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0baa\u0b95\u0bcd\u0b95\u0bb5\u0bbe\u0b9f\u0bcd\u0b9f\u0bbf\u0bb2\u0bcd \u0b87\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bc1 \u0bae\u0bc1\u0b9f\u0bbf\u0b9a\u0bcd\u0b9a\u0bc8 \u0b87\u0bb1\u0bc1\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Pull both loops tight, tight, tight!", "\u0b87\u0bb0\u0bc1 \u0bb5\u0bb3\u0bc8\u0baf\u0b99\u0bcd\u0b95\u0bb3\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b87\u0bb4\u0bc1\u0ba4\u0bcd\u0ba4\u0bc1 \u0b87\u0bb1\u0bc1\u0b95\u0bcd\u0b95\u0bc1!"),


            StepTuple("Check your shoelace", "\u0b95\u0bbe\u0bb2\u0ba3\u0bbf\u0b95\u0bcd \u0b95\u0baf\u0bbf\u0bb1\u0bcd\u0bb1\u0bc8\u0b9a\u0bcd \u0b9a\u0bb0\u0bbf\u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd", "Child confirms knot is secure.", "\u0bae\u0bc1\u0b9f\u0bbf\u0b9a\u0bcd\u0b9a\u0bc1 \u0b85\u0bb5\u0bbf\u0bb4\u0bbe\u0bae\u0bb2\u0bcd \u0b89\u0bb1\u0bc1\u0ba4\u0bbf\u0baf\u0bbe\u0b95 \u0b89\u0bb3\u0bcd\u0bb3\u0ba4\u0bbe \u0b8e\u0ba9 \u0b9a\u0bb0\u0bbf\u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bb5\u0bc1\u0bae\u0bcd.", "Look at your beautiful bow! You tied your shoes!", "\u0b85\u0bb4\u0b95\u0bbe\u0ba9 \u0bae\u0bc1\u0b9f\u0bbf\u0b9a\u0bcd\u0b9a\u0bc1 \u0baa\u0bcb\u0b9f\u0bcd\u0b9f\u0bbe\u0b9a\u0bcd\u0b9a\u0bc1! \u0b9a\u0baa\u0bbe\u0bb7\u0bcd!"),


        ),


    )


}


